import{_ as o,o as i,c as a,a2 as t}from"./chunks/framework.BN2sqjC1.js";const m=JSON.parse('{"title":"ADR-0049 — Editor Live su Milkdown (Crepe) con strato di conservazione del sorgente","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0049-editor-live-milkdown.md","filePath":"adr/0049-editor-live-milkdown.md"}'),n={name:"adr/0049-editor-live-milkdown.md"};function c(d,e,r,l,s,u){return i(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="adr-0049-—-editor-live-su-milkdown-crepe-con-strato-di-conservazione-del-sorgente" tabindex="-1">ADR-0049 — Editor Live su Milkdown (Crepe) con strato di conservazione del sorgente <a class="header-anchor" href="#adr-0049-—-editor-live-su-milkdown-crepe-con-strato-di-conservazione-del-sorgente" aria-label="Permalink to &quot;ADR-0049 — Editor Live su Milkdown (Crepe) con strato di conservazione del sorgente&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Stato</strong></td><td>accettata il 2026-11-12 (decisione dell&#39;owner: Milkdown è l&#39;unico motore Live e il predefinito, senza attendere le prove manuali del cancello A-W8: IME, spellcheck e lettori di schermo sulle tre WebView <strong>non sono state fatte</strong> e restano da fare, vedi «Esito di A-W9»); non ancora recepita nello spec. Implementata fino ad A-W9: l&#39;interruttore di build e il Live Preview di CodeMirror sono rimossi</td></tr><tr><td><strong>Data</strong></td><td>2026-11-10</td></tr><tr><td><strong>Riferimenti spec</strong></td><td>§2.3.1–§2.3.3 (editor, funzioni, pipeline e conformance), §2.6.6 (feature flag), §3.4.2 (contenuto <code>.md</code> a byte inalterati), §4.2 (layout del frontend, primitive UI); V-02/D-01, D-04, A-05; supera in parte <a href="./0004-live-preview.html">ADR-0004</a>; tocca ADR-0005, ADR-0020, ADR-0025, ADR-0048</td></tr><tr><td><strong>Devia dallo spec?</strong></td><td>sì → richiede aggiornamento di <code>Specifications.md</code> da parte dell&#39;owner: §2.3.1 (<code>:414</code>, Live Preview «con decorations e widget di CodeMirror 6»), §2.3.2 (<code>:419-429</code>, funzioni dell&#39;editor: multi-cursore, selezione rettangolare, numeri di riga, ricerca, completamento delle property; folding oltre i heading e riordino delle liste solo se non mantenuti, vedi §9), §2.3.3 (<code>:431-440</code>, e <code>:333</code> per la riga OFM: il consumatore «Rendering/Editor» non è più solo Lezer), §3.4.2 (<code>:1084</code>, byte inalterati: ora garantiti per costruzione da uno strato di conservazione), §4.2 (<code>:1746-1748</code>, cartella <code>editor/</code>; <code>:1769</code>, nessuna libreria di componenti esterna: Crepe porta Vue). <strong>Funzioni che in Live cambiano rispetto all&#39;editor di prima (ora per tutti gli utenti, dal 2026-11-12)</strong> (elenco e dettagli in §9): sintassi visibile sulla riga attiva (WYSIWYG); Invio in un paragrafo (paragrafo nuovo) e Shift+Invio (interruzione rigida); Tab e Shift+Tab; comandi di riga di <code>defaultKeymap</code> e <code>highlightSpecialChars</code> solo in Source; atomi raw non modificabili (commenti, <code>$$</code> in linea, definizioni e richiami di nota, note in linea, link e immagini a riferimento, autolink, riferimenti a caratteri, link con destinazione non canonica, HTML a blocco e in linea, titoli setext, codice indentato, e i blocchi interi che Live non sa proiettare: elenco in §9); emoji (<code>:smile:</code> digitato in Live scrive il carattere Unicode, resa Twemoji); <code>[[x</code> non chiuso scritto <code>\\[\\[x</code>; math in linea con il KaTeX di Crepe; popup slash proprio (con gruppi e icone); maniglia dei blocchi, barra sulla selezione, tooltip dei link e segnaposto del blocco vuoto, margini più larghi (passo M16-UX1); backtick non auto-appaiato; comando Tabella con celle vuote; regola sotto il testo di una voce stretta scritta <code>***</code>; spazi iniziali tolti dal testo che segue un incolla di blocchi a metà riga; numeri di riga, multi-cursore, selezione rettangolare, match della selezione, parentesi abbinate, riga attiva e completamento delle property solo in Source; colonna approssimata; ricerca sul testo reso; rinumerazione delle liste solo quando le cifre non cambiano; undo che non attraversa le modalità; oltre <code>LIVE_MAX</code> si apre Source; code block in carattere a spaziatura fissa e con meno margine interno; il primo Live aperto carica un chunk lazy</td></tr><tr><td><strong>Superfici</strong></td><td>desktop (editor Live, maniglia, strato di fedeltà; prove: vitest della suite di contratto, della conformance e del round-trip e di <code>live/chrome/chrome.test.ts</code>, <code>task e2e</code> sul mock dei binding, anche con <code>live-chrome.spec.ts</code>) · workbench web (stessa UI sul core WASM; prove sul core WASM nella matrice <code>e2e:workbench-ui</code>, richieste per le voci <code>editor.*</code> del registro, ADR-0045; <code>task test-wasm</code> prova invece il core Go compilato in WebAssembly, non l&#39;editor TypeScript) · console: nessuna · cloud: nessuna (il server non interpreta il contenuto, il merge resta sul client)</td></tr></tbody></table><h2 id="contesto" tabindex="-1">Contesto <a class="header-anchor" href="#contesto" aria-label="Permalink to &quot;Contesto&quot;">​</a></h2><p>La richiesta del 2026-11-10 è usare Milkdown (con tutte le feature di Crepe) come editor Markdown, mantenendo ogni funzione esistente. Oggi l&#39;editor è una sola vista CodeMirror 6 (<code>packages/workbench/src/editor/</code>, 24 file e 4359 righe contando i test) in cui Source e Live Preview sono lo stesso documento con un <code>Compartment</code> (ADR-0004, punto 1; da A-W9 non è più così: Source è un editor CodeMirror a modalità fissa, <code>editor/source/SourceEditor.tsx</code>, senza <code>Compartment</code> di modalità). La scelta dell&#39;utente: Milkdown sostituisce <strong>Live Preview</strong>; Source resta su CodeMirror 6 (<code>.marp</code> compresi) e Reading resta invariata.</p><p>ADR-0004 aveva scartato un editor ProseMirror/WYSIWYG perché il documento non sarebbe più il file Markdown (round-trip lossy, diff e merge più difficili). Il rischio è reale e va gestito per costruzione:</p><ul><li><code>Specifications.md:1084</code> impone che un <code>.md</code> viaggi a byte inalterati (nessuna normalizzazione di newline e BOM, hash sui byte grezzi); il merge a tre vie del client (<code>shared/go/merge</code>) lavora per righe, quindi una riscrittura di forma allarga gli hunk e produce conflitti falsi;</li><li>la serializzazione di Milkdown passa da remark e riscrive i marcatori (lista, enfasi, escape, indentazione) di tutto il documento;</li><li>tre nodi upstream riscrivono il contenuto: l&#39;immagine di Crepe trasforma l&#39;alt in <code>1.00</code> (mentre lo spec usa <code>|300</code>, <code>Specifications.md:424</code>), l&#39;emoji converte <code>:smile:</code> nel carattere al parsing, il Latex di Crepe riscrive i fence;</li><li>un <code>\\[[x]]</code> (fixture <code>link-escaped-brackets</code>), se un blocco sporco viene serializzato senza cautela, diventa un wikilink vero, cioè un backlink fantasma.</li></ul><p>Altri vincoli:</p><ul><li>l&#39;estrattore TS (<code>@memobrain/markdown</code>) e il parser Go (<code>goldmark</code>) sono già due parser con fixture condivise; le regole OFM inline non sono riusabili com&#39;è: <code>scanSpans</code> trova solo <code>%%</code> e <code>$$</code> (<code>packages/markdown/src/extract.ts:230-289</code>), il resto sta nella <code>scanLine</code> privata (<code>:341-423</code>, regex a <code>:67-75</code>) e tre regex vivono solo in <code>packages/workbench/src/editor/livePreview.ts:43-50</code> (<code>HIGHLIGHT</code>, <code>INLINE_MATH</code>, <code>FOOTREF</code>);</li><li><code>editor/registry.ts:5-27</code> espone un <code>EditorView</code> grezzo a 13 consumer che ragionano in righe e offset del sorgente (composer, daily, bookmarks, drawing, canvas, Marp, hover, comandi, <code>NoteView</code>);</li><li>il bundle iniziale del desktop è a 1979 kB su 2000 (<code>apps/desktop/frontend/scripts/esbuild.mjs:148-170</code>, <code>BUDGET</code>), il workbench web a 2500/23000 kB (<code>web/scripts/esbuild.mjs:328-336</code>); l&#39;esbuild del desktop collega solo il CSS dell&#39;entry (<code>:36-42</code>), quindi il CSS di un chunk lazy non verrebbe caricato (misura dello spike, poi smentita: il CSS dei chunk lazy era già nel <code>main.css</code>, §12);</li><li>CSP di produzione: <code>script-src &#39;self&#39; &#39;wasm-unsafe-eval&#39;</code>, <code>connect-src &#39;self&#39;</code>, niente <code>unsafe-eval</code> (<code>apps/desktop/internal/app/csp_prod.go:9-16</code>, ADR-0005); Vue deve girare nella sola build runtime;</li><li>Excalidraw e tutto il resto devono funzionare offline: emoji, linguaggi dei code block e asset vanno serviti dal bundle.</li></ul><p>Il piano che ha prodotto questo ADR (due progetti indipendenti e una critica avversariale; il piano adotta la base indicata dalla critica) non è versionato. I fatti su cui poggia, tratti dai sorgenti di Milkdown/Crepe, sono questi; lo spike A-W0 li ha poi riprovati sul pin 7.23.0 (esiti in «Verificato e non»):</p><ul><li><code>packages/crepe/src/feature/top-bar/component.tsx</code> e <code>config.ts</code>: pulsanti solo icona senza <code>aria-label</code>, nessun <code>role=&quot;toolbar&quot;</code>, niente undo/redo, titoli in inglese fisso, <code>buildTopBar</code> esistente;</li><li><code>packages/components/src/image-block/schema.ts</code>: in lettura <code>ratio = Number(alt) || 1</code>, in scrittura <code>alt = ratio.toFixed(2)</code>;</li><li><code>packages/plugins/plugin-emoji/src/index.ts</code>: <code>remark-emoji</code> converte <code>:smile:</code> al parsing;</li><li><code>packages/crepe/src/core/builder.ts</code>: <code>setReadonly</code> imposta <code>editable: () =&gt; false</code>;</li><li><code>plugin-highlight</code> si appoggia a <code>prosemirror-highlight</code>; <code>plugin-listener</code> serializza tutto il documento a ogni aggiornamento.</li></ul><p>I punti sono stati letti sul ramo <code>main</code>. Lo spike ha confermato sul 7.23.0 la TopBar, l&#39;image-block e l&#39;emoji; <code>plugin-highlight</code> si è rivelato inapplicabile ai code block di Crepe; <code>setReadonly</code> e <code>plugin-listener</code> non sono stati riprovati.</p><h2 id="decisione" tabindex="-1">Decisione <a class="header-anchor" href="#decisione" aria-label="Permalink to &quot;Decisione&quot;">​</a></h2><h3 id="_1-perimetro-e-motori" tabindex="-1">1. Perimetro e motori <a class="header-anchor" href="#_1-perimetro-e-motori" aria-label="Permalink to &quot;1. Perimetro e motori&quot;">​</a></h3><ul><li><strong>Live</strong> = Milkdown tramite <code>CrepeBuilder</code> (<code>@milkdown/crepe</code>, pin <strong>esatto 7.23.0</strong>), con tutte le feature di Crepe, più emoji con asset locali, <code>plugin-highlight</code>, automd, upload, diff e streaming (all&#39;implementazione <code>plugin-highlight</code> e automd non sono stati usati e l&#39;upload è sostituito da <code>saveAttachment</code>: vedi §12). <strong>Source</strong> = CodeMirror 6 invariato, e così i <code>.marp</code> (ADR-0047/0048). <strong>Reading</strong> = <code>ReadingView</code>, invariata.</li><li><strong>Un solo motore attivo per pane.</strong> Al cambio Live↔Source si smonta Milkdown o lo si monta con il testo corrente; il CodeMirror di Source resta montato, sospeso, sotto Live, come spina dell&#39;undo e del ripiego (§6), e non è mai modificabile mentre Live è attivo. Scartato il doppio editor sincronizzato del playground di Milkdown: due cronologie e riscrittura totale a ogni cambio.</li><li>ADR-0004 resta valido per Source, per Reading (punto 7) e per il ponte <code>LivePreviewContext</code> (punto 5: da A-W9 resta l&#39;interfaccia di <code>editor/context.ts</code>, che <code>NoteView</code> passa a <code>NoteEditor</code> come prop <code>context</code> e che usano le viste dei nodi Milkdown; il <code>Facet</code> di CodeMirror non esiste più); decade per Live Preview la parte «un solo documento CodeMirror», «decorazioni, non trasformazioni», «sintassi sulla riga del cursore» e «widget a blocchi» (punti 1–4); il punto 6 (tasti) resta per Source e Live usa un listener in cattura (vedi §6).</li></ul><h3 id="_2-il-sorgente-markdown-e-l-unica-fonte-di-verita" tabindex="-1">2. Il sorgente Markdown è l&#39;unica fonte di verità <a class="header-anchor" href="#_2-il-sorgente-markdown-e-l-unica-fonte-di-verita" aria-label="Permalink to &quot;2. Il sorgente Markdown è l&#39;unica fonte di verità&quot;">​</a></h3><p>Nessun consumer vede posizioni ProseMirror. <code>useNoteDocument</code> (salvataggio, <code>expectedHash</code>, conflitto, rescue copy) è già indipendente dal motore, perché riceve un getter pigro (<code>useNoteDocument.ts:27</code>) e resta com&#39;è.</p><h3 id="_3-noteeditorhandle-al-posto-di-editorview" tabindex="-1">3. <code>NoteEditorHandle</code> al posto di <code>EditorView</code> <a class="header-anchor" href="#_3-noteeditorhandle-al-posto-di-editorview" aria-label="Permalink to &quot;3. `NoteEditorHandle` al posto di `EditorView`&quot;">​</a></h3><p><code>editor/registry.ts</code> passa a <code>Map&lt;string, NoteEditorHandle&gt;</code> (file <code>editor/handle.ts</code> e <code>editor/types.ts</code>). L&#39;interfaccia è semantica, senza offset dentro un blocco e senza scappatoie verso la view:</p><ul><li><code>kind</code>, <code>paneId</code>, <code>root</code>, <code>focus()</code>, <code>readOnly()</code></li><li><code>text()</code> (pigro e memoizzato), <code>cursor()</code>, <code>selectionMarkdown()</code></li><li><code>replaceSelection</code>, <code>replaceSelectionIf</code> (composer), <code>appendToLine</code> (segnalibri <code>^id</code>)</li><li><code>applySourceEdits(base, edits)</code> per Marp, con <code>SourceEdit {from,to,insert}</code> al posto di <code>ChangeSpec</code></li><li><code>exec(cmd, arg)</code> per formattazione, undo e redo</li><li><code>reveal({line|heading|block})</code>, <code>gotoLine</code>, <code>linkAt</code>, <code>stats()</code>, <code>openSearch()</code></li><li><code>snapshot()</code> / <code>restore()</code> in righe sorgente (selezione e scroll)</li></ul><p>Regola per la selezione in barra di stato: tutto selezionato dà i totali, altrimenti conta la lunghezza di <code>selectionMarkdown()</code>. Le voci di <code>slash/</code> diventano id di comando, non funzioni su <code>EditorView</code>. Una regola ESLint vieta <code>@codemirror/*</code> fuori da <code>editor/source</code>. Una sola suite di contratto (<code>editor/handle.contract.test.ts</code>) gira su entrambi gli adattatori.</p><h3 id="_4-strato-di-conservazione-del-sorgente-per-blocco" tabindex="-1">4. Strato di conservazione del sorgente (per blocco) <a class="header-anchor" href="#_4-strato-di-conservazione-del-sorgente-per-blocco" aria-label="Permalink to &quot;4. Strato di conservazione del sorgente (per blocco)&quot;">​</a></h3><ul><li><strong>Busta:</strong> BOM, frontmatter (<code>splitFrontmatter</code>, <code>extract.ts:78</code>), EOL dominante e newline finali sono staccati e ricuciti byte per byte. Il frontmatter non entra in Milkdown, quindi resta nascosto e protetto per costruzione (le property si modificano dal pannello, come oggi).</li><li><strong>Tabella dei blocchi</strong> dalle <code>position</code> di mdast, fino al secondo livello (voci di lista, figli di blockquote e di callout). Allineamento dei blocchi correnti agli originali per identità del nodo, poi per <code>node.eq</code> (copre undo e spostamenti).</li><li><strong>Blocco non toccato:</strong> fetta originale, con il suo separatore e il suo EOL. <strong>Blocco modificato:</strong> serializzazione del solo blocco, con stile (marcatore di lista, enfasi, regola, fence, indentazione) dedotto dal file. I separatori di slide (<code>---</code>) restano <code>-</code>; <code>***</code> solo in testa, perché un <code>---</code> come primo blocco verrebbe riletto come frontmatter da <code>splitFrontmatter</code>.</li><li><strong><code>raw_block</code> e <code>raw_inline</code></strong> per ciò che non ha uno schema (HTML a blocco, link reference, codice indentato, setext): riemessi tali e quali.</li><li><strong>Nodi upstream da sovrascrivere:</strong> image-block (alt conservato e larghezza <code>|W</code>), emoji (nessuna conversione al parsing, solo input rule e resa twemoji), Latex di Crepe (forma originale in un attributo).</li><li><strong>Reload esterno:</strong> la tabella si ricostruisce dal nuovo testo per tutti i blocchi (un cambio solo di forma, come <code>-</code>→<code>*</code> o CRLF, non deve restare invisibile). Il cambio del solo frontmatter sostituisce la busta, senza transazione.</li><li><strong>Nessuna scrittura senza input dell&#39;utente.</strong> <code>onChange</code> parte solo da transazioni con <code>docChanged</code> non <code>External</code>. Lo stato di vista (fold dei callout) è stato di plugin, mai un attributo del documento.</li><li><strong>Guardia a runtime:</strong> se parse o composizione falliscono, il file si apre in Source con un avviso.</li></ul><h3 id="_5-regole-ofm-da-un-unica-sorgente-e-conformance-a-tre-parser" tabindex="-1">5. Regole OFM da un&#39;unica sorgente e conformance a tre parser <a class="header-anchor" href="#_5-regole-ofm-da-un-unica-sorgente-e-conformance-a-tre-parser" aria-label="Permalink to &quot;5. Regole OFM da un&#39;unica sorgente e conformance a tre parser&quot;">​</a></h3><ul><li>Da <code>@memobrain/markdown</code> si esporta <code>scanInline(line, state)</code> con span tipizzati; <code>scanLine</code> si ricostruisce su di esso; vi si spostano le tre regex di <code>livePreview.ts</code> e <code>parseCalloutHead</code> (oggi in <code>editor/callouts.ts</code>). Così indice, Reading e Live condividono le regole.</li><li>Il plugin remark scandisce le righe sorgente intere e proietta gli span sull&#39;mdast per <code>position</code>; uno span non proiettabile, o un blocco dentro uno span multi-riga, diventa <code>raw_block</code>.</li><li><strong>Invariante di escape</strong>, come test di proprietà bloccante: i costrutti che <code>extract()</code> trova nel blocco serializzato coincidono con i nodi OFM del blocco. L&#39;handler <code>text</code> mette l&#39;escape solo sugli span che <code>scanInline</code> riconoscerebbe nel proprio output.</li><li>Wikilink ed embed sono nodi inline con contenuto testuale grezzo, rivelato quando il cursore è dentro. Tag, highlight, commento e <code>^id</code> sono mark o decorazioni, non atomi (un atomo creato a <code>#ta</code> spezzerebbe la digitazione).</li><li><strong>Terzo parser</strong> nel regime di conformance (<code>Specifications.md:431-440</code>, ADR-0036): <code>packages/workbench/src/test/conformance.test.ts</code>, che <code>Taskfile.yml:222</code> esegue già in <code>task conformance</code> se il file esiste. Corpus di round-trip in <code>shared/conformance/roundtrip/</code> (da escludere da Prettier). Bloccanti: invariante di escape, identità con blocchi puliti, località a righe, dieci giri idempotenti.</li></ul><h3 id="_6-convivenza-con-le-funzioni-esistenti" tabindex="-1">6. Convivenza con le funzioni esistenti <a class="header-anchor" href="#_6-convivenza-con-le-funzioni-esistenti" aria-label="Permalink to &quot;6. Convivenza con le funzioni esistenti&quot;">​</a></h3><ul><li><strong>Toolbar:</strong> <code>EditorToolbar</code> resta la barra del documento in entrambe le modalità, via <code>handle.exec</code>. La TopBar di Crepe resta spenta (nessun nome accessibile, i18n né undo/redo; una <code>yarn patch</code> di Crepe richiede il consenso dell&#39;owner). Dal passo M16-UX1 <code>EditorToolbar</code> non è più l&#39;unica barra in Live: la barra flottante <strong>sulla selezione</strong> di Crepe (<code>toolbar</code>) è accesa con i nomi, le icone e le scorciatoie dell&#39;applicazione (§9, <code>live/chrome/</code>). Non la sostituisce: <code>EditorToolbar</code> resta la via da tastiera.</li><li><strong>Slash:</strong> una sola lista di voci e le stesse regole (<code>slash/items.ts</code>), rese dal popup proprio di Live (<code>live/input/suggest.ts</code>, con gruppi e icone) e dalla completion CM in Source; escluso in codice e math. <code>blockEdit</code> di Crepe non si usa (vedi «Alternative considerate»). <strong>Completamenti:</strong> <code>completions.ts</code> si divide in motore agnostico e due adattatori; il ranking resta nel backend.</li><li><strong>Incolla e upload:</strong> lo smart paste ha la precedenza su <code>plugin-clipboard</code>; l&#39;uploader di Crepe è sostituito da <code>saveAttachment</code> (<code>paste.ts</code>). I provider <code>@milkdown/crepe/llm-providers/*</code> sono vietati (ADR-0050).</li><li><strong>Hotkey:</strong> listener <code>keydown</code> in fase di cattura sulla radice Live, con guardia <code>isComposing</code>, verso <code>commandForEvent</code>; <code>handleKeyDown</code> di ProseMirror non vede i tasti nei code block annidati né nei tooltip.</li><li><strong>Sola lettura:</strong> <code>filterTransaction</code> che rifiuta le modifiche non <code>External</code>, con l&#39;editor che resta focalizzabile (<code>setReadonly</code> di Crepe toglie il focus e spegne Ln/Col e i comandi).</li><li><strong>Ricerca:</strong> <code>FindBar</code> propria (<code>live/frame/find.ts</code>, <code>findBar.ts</code>), senza <code>prosemirror-search</code> (non installato, §12), con regex, maiuscole e «sostituisci tutto».</li><li><strong><code>plugin-highlight</code></strong> sarebbe la colorazione del codice, non <code>==highlight==</code> (che resta una mark OFM); lo spike l&#39;ha trovato inapplicabile ai code block di Crepe, che sono CodeMirror, e non si usa (§12).</li><li><strong>Tema:</strong> solo le variabili <code>--crepe-*</code> mappate sui token di <code>@memobrain/ui</code>: nessun CSS dell&#39;utente (D-01). Stringhe in <code>i18n/{it,en}.json</code>.</li><li><strong>Undo fra modalità:</strong> lo stato CodeMirror resta la spina; il risultato di Live vi entra come una transazione a diff minimo: la sessione Live si annulla in un solo passo di undo da Source.</li><li><strong>Interruttore del motore: rimosso in A-W9 (2026-11-12).</strong> Era una costante di build <code>MEMOBRAIN_LIVE_ENGINE</code>, sul modello di <code>MEMOBRAIN_E2E</code>, mai persistita nel vault e non un flag del Config Profile; le spec dell&#39;editor giravano sui due motori fino al cancello di parità. Con la decisione dell&#39;owner Milkdown è l&#39;unico motore Live: il plugin di risoluzione <code>liveEngine</code> non esiste più, <code>NoteEditor.live.tsx</code> è diventato <code>NoteEditor.tsx</code>, e sono stati cancellati <code>livePreview.ts</code>, <code>blockWidgets.ts</code>, <code>widgets.ts</code>, <code>callouts.ts</code>, <code>query/widget.ts</code>, il <code>Facet</code> <code>livePreviewContext</code> e i selettori <code>.cm-lp-*</code>, <code>.cm-wikilink*</code> e <code>.cm-callout*</code>. Restano le costanti di AI e collaborazione (ADR-0050) e <code>MEMOBRAIN_E2E</code>.</li></ul><h3 id="_7-bundle-csp-offline" tabindex="-1">7. Bundle, CSP, offline <a class="header-anchor" href="#_7-bundle-csp-offline" aria-label="Permalink to &quot;7. Bundle, CSP, offline&quot;">​</a></h3><ul><li>Tutto Milkdown in chunk lazy con <code>importWithRetry</code> (<code>ui/lazyView.ts:23</code>, già usato per i chunk di Marp, <code>marp/commands.ts:73</code>): editor, linguaggi dei code block, emoji, AI, collab. Nel bundle iniziale restano handle, loader e adattatore CodeMirror. Il margine di 21 kB di partenza sul bundle iniziale era condiviso con ADR-0051; con A-W9 l&#39;entry desktop è di 1376 kB su 2000 (margine circa 624 kB, §12): il Live non è più nell&#39;entry e il peso del vecchio Live è sparito.</li><li>CSS dei chunk lazy: esbuild lo mette già nel <code>main.css</code>, quindi il collegamento per chunk non cambia l&#39;aspetto (§12, <code>linkLazyStyles</code> è una rete di sicurezza); i <code>define</code> di Vue non hanno effetto utile (6 kB in totale, 0 sull&#39;entry: criterio 5 dello spike) e Vue resta nella sola build runtime, senza <code>unsafe-eval</code>. Budget web da rispettare: 2500/23000 kB.</li><li>Emoji (twemoji) e dati dei linguaggi come asset locali; zero richieste di rete e zero violazioni della CSP di produzione, verificati dagli e2e.</li><li><strong>Vue e <code>Specifications.md:1769</code>.</strong> Crepe porta Vue, mentre lo spec vieta una libreria di componenti esterna per l&#39;interfaccia dell&#39;applicazione. La decisione è: Vue è confinato dentro il chunk lazy dell&#39;editor, come dettaglio di implementazione di Crepe; le primitive dell&#39;app restano <code>@memobrain/ui</code> (React). Lo spec va aggiornato per ammettere l&#39;eccezione; è un punto da far confermare all&#39;owner.</li></ul><h3 id="_8-prestazioni" tabindex="-1">8. Prestazioni <a class="header-anchor" href="#_8-prestazioni" aria-label="Permalink to &quot;8. Prestazioni&quot;">​</a></h3><p>Nessun listener <code>markdownUpdated</code> (serializza tutto ogni 200 ms). Composizione pigra e memoizzata: <code>NoteView.tsx:293</code> chiama <code>doc.current()</code> a ogni render. Soglia <code>LIVE_MAX</code> (caratteri, blocchi, blocco massimo, numero di code block) oltre la quale la nota si apre in Source con avviso, calibrata nello spike.</p><h3 id="_9-deviazioni-elencate-funzioni-che-in-live-cambiano" tabindex="-1">9. Deviazioni elencate (funzioni che in Live cambiano) <a class="header-anchor" href="#_9-deviazioni-elencate-funzioni-che-in-live-cambiano" aria-label="Permalink to &quot;9. Deviazioni elencate (funzioni che in Live cambiano)&quot;">​</a></h3><p>Elenco delle differenze trovate, verificate sul codice e sui test fino ad A-W7 (2026-11-11) e aggiornate nella fase di consolidamento (2026-11-12). Non è una prova che non ce ne siano altre: la prova manuale di A-W8 sulle tre WebView (IME, spellcheck, lettore di schermo) può aggiungerne. Dal 2026-11-12 (A-W9) valgono per tutti gli utenti, perché Milkdown è l&#39;unico motore Live. Le righe valgono per Live: Source (CodeMirror) non cambia, salvo dove indicato in «Cambiano anche fuori da Live Milkdown».</p><table tabindex="0"><thead><tr><th>Funzione</th><th>In Live con Milkdown</th></tr></thead><tbody><tr><td>Sintassi visibile sulla riga attiva</td><td>Sostituita dal WYSIWYG; wikilink ed embed mostrano il sorgente quando il cursore è dentro o accanto; i commenti <code>%%…%%</code> restano nascosti finché il cursore non li tocca</td></tr><tr><td>Invio in un paragrafo</td><td>Crea un paragrafo nuovo separato da una riga vuota (<code>abc</code>, Invio, <code>def</code> dà <code>abc\\n\\ndef</code>); in Source inserisce un solo <code>\\n</code></td></tr><tr><td>Shift+Invio</td><td>Scrive un&#39;interruzione di riga rigida (<code>\\</code> e a capo)</td></tr><tr><td>Tab e Shift+Tab</td><td>In una lista, Tab affonda la voce e Shift+Tab la riporta su (una prima voce o una di livello alto non scrive nulla). In un paragrafo, Tab scrive un carattere di tabulazione nel punto del cursore (mai spazi) e Shift+Tab lo toglie; con una selezione o all&#39;inizio del blocco non scrive nulla. Nelle celle sposta alla cella successiva o precedente. Tab non esce più dall&#39;editor, come <code>indentWithTab</code> in Source: non c&#39;è una via d&#39;uscita da tastiera</td></tr><tr><td>Comandi di riga di <code>defaultKeymap</code>, caratteri speciali</td><td>Copia, elimina e seleziona riga, <code>Mod-/</code> e la resa dei caratteri speciali (<code>highlightSpecialChars</code>): solo in Source</td></tr><tr><td>Atomi raw non modificabili</td><td>Il testo di questi costrutti non si modifica in Live: sono nodi <code>raw_inline</code> e <code>raw_block</code> riemessi tali e quali (<code>ofm/remark.ts</code>, <code>views/raw.ts</code>); si selezionano, si spostano o si cancellano interi, e si modificano solo in Source (prima erano testo modificabile). <strong>A blocco:</strong> commenti <code>%%…%%</code>, definizioni di nota a piè di pagina e di link, HTML, titoli setext (<code>Titolo</code> e <code>===</code>), codice indentato, math a blocco con più parole nella riga di apertura (il <code>$$</code> semplice è invece un code block LaTeX modificabile). <strong>In linea:</strong> commenti <code>%%…%%</code> e math <code>$$…$$</code>; HTML (<code>&lt;br&gt;</code>, <code>&lt;b&gt;</code>: alcune coppie di tag si vedono con lo stile, il testo resta sorgente); richiami di nota <code>[^1]</code> e note in linea <code>^[…]</code>; link e immagini a riferimento (<code>[t][r]</code>, <code>![a][r]</code>); autolink (<code>&lt;https://…&gt;</code> e indirizzi nudi); riferimenti a caratteri (<code>&amp;amp;</code>, <code>&amp;#35;</code>); link e immagini con destinazione non canonica (spazi, parentesi, <code>&lt;…&gt;</code>, escape o riferimenti a caratteri) e link senza testo. <strong>Blocchi interi:</strong> un paragrafo, un titolo, una tabella, una lista o una citazione diventa un solo atomo quando uno span OFM non si proietta sul testo (attraversa il bordo del blocco o si sovrappone a un altro), quando due mark uguali si annidano (<code>*a *b* c*</code>, un link in un link), quando una cella di tabella non si può proiettare, quando un commento o un <code>$$</code> su più righe lo tocca, quando una voce di lista non comincia con un paragrafo o una lista ne contiene un&#39;altra direttamente, e quando riscritto da solo non dà lo stesso albero e lo stesso <code>extract()</code> (cancello di stabilità, §12)</td></tr><tr><td>Wikilink non chiuso</td><td><code>[[x</code> senza chiusura si scrive <code>\\[\\[x</code> finché non si chiude</td></tr><tr><td>Emoji</td><td>Digitare <code>:smile:</code> in Live scrive nel file il carattere Unicode (😄) con la regola di input di <code>@milkdown/plugin-emoji</code>; in Source resta <code>:smile:</code>. Un <code>:smile:</code> già nel file non si converte (<code>remark-emoji</code> non è installato) e <code>a:b:c</code> resta com&#39;è. In Live ogni emoji Unicode del testo si vede come immagine Twemoji locale (<code>/emoji/svg/</code>), mentre il file conserva il carattere. La conversione fa parte del plugin emoji richiesto ed è accettata come deviazione di scrittura</td></tr><tr><td>Richiami di nota e link a riferimento</td><td>Un <code>[^1]</code> si digita o si incolla in Live e diventa un atomo (<code>live/input/refs.ts</code>), come quello letto dal file: si scrive tale e quale. Lo stesso per <code>[testo][r]</code> e <code>[r][]</code> quando la nota ha la definizione <code>[r]:</code> (anche se è nell&#39;incollato). Deviazione: un <code>[testo][r]</code> senza definizione nella nota resta testo e si scrive con l&#39;escape (<code>\\[testo]\\[r]</code>, come <code>a[i][j]</code>); si risolve scrivendo prima la definizione, o in Source, dove il riferimento resta com&#39;è. Un <code>\\[^1]</code> incollato con l&#39;escape è il testo che dice.</td></tr><tr><td>Math in linea</td><td><code>$x$</code> è reso dalla vista KaTeX di Crepe, non da <code>renderMath</code> dell&#39;applicazione (che resta per <code>$$…$$</code>)</td></tr><tr><td>Menu slash</td><td>Stessa lista di voci, stesso innesco e stesse regole di Source, ma il popup è nostro, non <code>block-edit</code> di Crepe. In Live le voci sono in gruppi (Testo, Elenchi, Avanzati, Vault: <code>slash.group.*</code>) con un&#39;icona ciascuna (<code>input/slashLook.ts</code>; una voce senza gruppo va in Avanzati, senza icona), e le etichette sono senza la «/» davanti (Source resta con «/Heading 1»)</td></tr><tr><td>Maniglia dei blocchi</td><td>Nuova, come nel playground di Milkdown (<code>live/chrome/handle.ts</code>, costruita sul plugin dei blocchi <code>@milkdown/kit/plugin/block</code>): un «+» e una presa accanto al blocco sotto il puntatore. Il «+» aggiunge un blocco vuoto sotto (un paragrafo; accanto a una voce di lista una voce nuova, senza casella; un paragrafo vuoto già sotto la maniglia si riusa) con il caret dentro, e apre lì il popup slash, che si chiude come quello digitato (Esc, clic fuori, testo che non è più una ricerca); con <code>slashCommands</code> spento aggiunge solo il blocco. La presa trascina il blocco con il trascinamento di ProseMirror, e il drop passa dallo strato di fedeltà (gli altri blocchi restano scritti com&#39;erano). Non compare dentro tabelle e citazioni (i callout sono citazioni: si spostano interi), nei pane più stretti di 420 px (<code>data-size=&#39;narrow&#39;</code>) né in sola lettura. <strong>È solo per il puntatore:</strong> i due controlli non sono nell&#39;ordine di tabulazione; il «+» ha un nome per i lettori di schermo (<code>editor.crepe.addBlock</code>) e risponde a un clic che non viene da un puntatore (quello di un lettore di schermo); la presa è nascosta ai lettori di schermo (<code>aria-hidden</code>, col solo <code>title</code> <code>editor.crepe.dragBlock</code>), perché un loro clic selezionerebbe il blocco e il testo digitato dopo lo sostituirebbe. Gli equivalenti da tastiera sono <code>/</code> per il menu e Alt+↑/↓ per spostare il blocco</td></tr><tr><td>Barra sulla selezione</td><td>Nuova: la barra flottante di Crepe (<code>toolbar</code>) compare su una selezione di testo con grassetto, corsivo, barrato, evidenziato (<code>==</code>), codice, formula in linea e link. I pulsanti hanno il nome tradotto, le icone del set dell&#39;applicazione e le scorciatoie del registro dei comandi (comprese quelle cambiate dall&#39;utente), non quelle che Milkdown lega alle stesse marche; la formula in linea non ha un comando nel registro e quindi nessuna scorciatoia. La barra ha <code>role=toolbar</code> e un nome. Il pulsante «Chiedi all&#39;AI» <strong>non c&#39;è</strong>: la barra di Crepe lanciava un&#39;eccezione leggendo la configurazione dell&#39;AI, quindi <code>attachAi</code> toglie il flag <code>ai</code> da <code>FeaturesCtx</code> (<code>live/ai/feature.ts</code>); l&#39;AI resta inattiva (ADR-0050). Non compare in sola lettura, e scrive solo il blocco in cui sta la selezione</td></tr><tr><td>Tooltip dei link</td><td>Nuovo: il tooltip di Crepe (<code>link-tooltip</code>) compare sul clic di un link Markdown <code>[testo](url)</code> e permette di copiare, modificare e rimuovere il link; i pulsanti sono icone con un nome per i lettori di schermo e il campo ha un nome. «Link copiato» è un avviso in una regione <code>aria-live</code> sempre presente. <strong>Solo per i link Markdown:</strong> i wikilink non sono link per Milkdown e restano con Mod+clic e anteprima al passaggio. Non compare in sola lettura</td></tr><tr><td>Segnaposto del blocco vuoto</td><td>Nuovo: il blocco vuoto che ha il caret mostra «Scrivi, oppure premi / per i comandi» (con <code>slashCommands</code> spento «Scrivi qui»; il testo segue l&#39;impostazione mentre cambia). Non compare nelle tabelle, nei code block, nelle liste né in sola lettura, e non entra mai nel file</td></tr><tr><td>Margini e larghezza di lettura</td><td>Più larghi, come nel playground (<code>live/theme.css</code>): a sinistra c&#39;è il posto della maniglia e del chevron del fold (112 px in un pane largo, 84 compatto, 28 stretto; a destra 56, 28 e 16). La classe <code>data-size</code> (<code>wide</code>, <code>compact</code> sotto 640 px, <code>narrow</code> sotto 420 px) la scrive un <code>ResizeObserver</code> sull&#39;host dell&#39;editor, quindi misura il pane e non la finestra; non è una container query, perché <code>contain</code> romperebbe il popup slash, che è <code>position: fixed</code>. Con <code>readableWidth</code> la riga di testo è di 712 px e il <code>.ProseMirror</code> arriva a 880 px in un pane largo (712 più i due margini; prima erano 760 px in tutto)</td></tr><tr><td>Auto-chiusura delle coppie</td><td>Il backtick non si auto-appaia, per lasciare la regola del codice inline</td></tr><tr><td>Comando Tabella</td><td>Dà una tabella con le celle vuote, non «Column 1» e «Column 2»</td></tr><tr><td>Regola sotto il testo di una voce stretta</td><td>Si scrive <code>***</code>, anche se il file usa <code>---</code> o l&#39;utente ha digitato o incollato <code>---</code> (<code>ruleHandler</code> in <code>kit.ts</code>): un <code>---</code> subito sotto il testo è la sottolineatura di un titolo setext, e il task sparirebbe. La voce resta stretta come la mostra l&#39;editor; dove la regola non segue un testo resta il marcatore del file</td></tr><tr><td>Incolla di blocchi a metà riga</td><td>Il testo che segue i blocchi incollati comincia un blocco suo, senza gli spazi iniziali che aveva (nell&#39;editor e nel file: niente <code>&amp;#x20;</code>, <code>replaceWithBlocks</code> in <code>input/paste.ts</code>). In una voce stretta, un paragrafo che segue una lista, una citazione o una tabella è scritto dopo una riga bianca, e la voce diventa larga (è il solo modo di dirlo nel file)</td></tr><tr><td>Numeri di riga, multi-cursore, selezione rettangolare</td><td>Solo in Source</td></tr><tr><td>Colonna in barra di stato</td><td>Riga esatta, colonna approssimata dentro il blocco</td></tr><tr><td>Cerca e sostituisci</td><td>Cerca il testo reso, non i marcatori Markdown; dentro un wikilink cerca il testo grezzo, non l&#39;alias visibile. La ricerca è propria (<code>live/frame/find.ts</code>), non <code>prosemirror-search</code></td></tr><tr><td>Impostazioni dell&#39;editor</td><td><code>tabSize</code> vale per i code block e per <code>tab-size</code>; i figli di lista usano lo stile dedotto dal file</td></tr><tr><td>Completamento dei nomi di property</td><td>Solo in Source, perché il frontmatter è fuori da Live</td></tr><tr><td>Match della selezione, parentesi abbinate, riga attiva</td><td>Solo in Source</td></tr><tr><td>Rinumerazione delle liste ordinate</td><td>Dopo che una voce arriva o va via la lista si riconta, come Source dopo Invio. Non si toccano le liste che non contano (tutte <code>1.</code>) né quelle in cui un numero cambierebbe cifre (da 9 a 10): lì restano numeri doppi</td></tr><tr><td>Undo fine che attraversa Live↔Source</td><td>L&#39;undo fine non attraversa il cambio di modalità (oggi lo fa, perché è la stessa view; passando da Reading l&#39;editor si smonta già e la cronologia si perde); la sessione Live si annulla in un solo passo da Source (§6)</td></tr><tr><td>Documenti oltre <code>LIVE_MAX</code></td><td>Si aprono in Source con avviso (soglie in §12)</td></tr><tr><td>Primo Live aperto</td><td>L&#39;editor Live è un chunk lazy: la prima nota aperta in Live ne attende il caricamento (circa 0,8 s a freddo nella misura di A-W8, in Chromium headless; non misurato su una WebView vera) e, finché non è pronto, la nota si vede in Source in sola lettura</td></tr><tr><td>Code block</td><td>Il codice dei code block è nel carattere a spaziatura fissa dell&#39;applicazione (<code>--crepe-font-code</code>; il tema proprio di CodeMirror dentro Crepe nomina il generico <code>monospace</code>) e il margine interno è più stretto: le regole <code>.editor-host .cm-*</code> dell&#39;editor Sorgente valgono ora solo per Source (<code>.editor-host[data-mode=&#39;source&#39;]</code>), e una vecchia regola <code>[data-mode=&#39;live&#39;] .cm-scroller</code> faceva usare ai code block il carattere dell&#39;interfaccia</td></tr><tr><td>Ricerca nella nota (<code>editor:find</code>)</td><td>In Live è la barra propria di Live (testo reso, espressioni regolari, maiuscole, sostituisci tutto); il pannello di ricerca di CodeMirror (<code>@codemirror/search</code>) c&#39;è solo in Source</td></tr><tr><td>File CRLF</td><td>Migliora: con CodeMirror un file CRLF modificato viene salvato tutto in LF; in Live i blocchi non toccati conservano CRLF (1074 file su 1074 del corpus, §Verificato e non)</td></tr></tbody></table><p><strong>Mantenute in Live</strong> (erano «da mantenere» o a rischio; non sono deviazioni):</p><ul><li><strong>Folding</strong> di heading, voci di lista con figli, blockquote non callout, code block e tabelle (<code>live/frame/fold.ts</code>). Lo stato di vista sta nel plugin, mai nel documento; un fold si apre da solo se il cursore o una ricerca ci entra; i tasti sono quelli di <code>foldKeymap</code>; <code>foldHeadings</code> comanda anche Live. Il chevron di un blocco aperto è un solo bottone che segue il puntatore.</li><li><strong>Riordino</strong> con Alt+↑/↓ di voci di lista (con i figli) e di blocchi, mai in tabelle e code block (<code>exec(&#39;move-up&#39;|&#39;move-down&#39;)</code>); il trascinamento con la presa della maniglia passa dallo stesso strato. Spostare un blocco oltre una regola orizzontale ne conserva la regola e il blocco (prima di M16-UX1 la regola spariva e il blocco si duplicava: vedi «Consolidamento, passo M16-UX1»).</li><li><strong>Casella dei task</strong> con <code>role=checkbox</code>, <code>aria-checked</code>, <code>tabindex</code> e nome tradotto (<code>editor.crepe.task</code>); Spazio, Invio e il clic senza puntatore la attivano, anche per gli stati personalizzati (<code>aria-checked=mixed</code>).</li><li><strong>Incolla di testo semplice</strong>: il testo passa dal parse diretto e non da <code>plugin-clipboard</code>, quindi <code>[[…]]</code>, <code>![[…]]</code>, <code>$$…$$</code>, <code>%%…%%</code> e le note a piè di pagina restano come scritti (come in Source). Nelle celle gli a capo diventano spazio. Restano al plugin l&#39;incolla dentro un code block, dentro il testo di un wikilink e le copie dell&#39;editor stesso (<code>data-pm-slice</code>).</li><li><strong>Comando Callout</strong>: scrive <code>[!note] </code> con lo spazio e il cursore dopo; <strong>spazi finali</strong> di un blocco riscritto: escono letterali, non come <code>&amp;#x20;</code>.</li></ul><p><strong>Cambiano anche fuori da Live Milkdown</strong> (visibile a tutti):</p><ul><li>In Source: le voci dello slash con il segnaposto <code>|</code> sono comandi (<code>exec</code>): <code>/callout</code> e <code>/divider</code> a metà riga iniziano su una riga propria, e <code>/table</code> inserisce la tabella intera (prima il primo <code>|</code> era preso per il segnaposto del cursore e spariva).</li><li>In Live, non in Source: Mod+clic su un <code>#tag</code> apre la ricerca <code>tag:#nome</code> (prima non faceva nulla). In Source il clic non ha gestori e il tag non si segue. <code>tagSearchOf</code> in <code>editor/linkSpec.ts</code>, usato da <code>NoteView</code>; il clic è gestito da <code>live/views/interactions.ts</code>.</li><li>In tutte le modalità: nuovi comandi <code>editor:find</code> (Mod-f) e <code>editor:goto-line</code> (Mod-Alt-g, con dialogo).</li></ul><p><strong>Limiti di accessibilità noti</strong> (da guardare nella prova con lettore di schermo di A-W8): gli e2e spengono le regole axe <code>list</code> e <code>listitem</code> sui contenuti di Crepe (avvolge i <code>li</code> in un <code>div</code>, non correggibile senza una patch di Crepe); i controlli di riga e colonna delle tabelle di Crepe si usano solo col puntatore (da tastiera ci sono i comandi di cella). Dal passo M16-UX1 lo stesso vale per la maniglia dei blocchi, per i pulsanti del tooltip dei link e per quelli della barra sulla selezione: hanno un nome per i lettori di schermo (<code>aria-label</code> o testo <code>live-sr</code>; <code>role=toolbar</code> e nome per la barra; la presa della maniglia è invece <code>aria-hidden</code>), e il «+» e le icone del tooltip rispondono a un clic senza puntatore, ma non stanno nell&#39;ordine di tabulazione; ciò che fanno ha tasti propri (<code>/</code>, Alt+↑/↓, le scorciatoie di formattazione). La TopBar di Crepe resta spenta; <code>EditorToolbar</code> è la barra del documento accessibile da tastiera. Non provato con un lettore di schermo vero (VoiceOver, NVDA, Orca).</p><h3 id="_10-collaborazione-in-tempo-reale-integrata-e-spenta" tabindex="-1">10. Collaborazione in tempo reale: integrata e spenta <a class="header-anchor" href="#_10-collaborazione-in-tempo-reale-integrata-e-spenta" aria-label="Permalink to &quot;10. Collaborazione in tempo reale: integrata e spenta&quot;">​</a></h3><p>L&#39;integrazione Yjs lato client (<code>plugin-collab</code>) è un chunk lazy dietro il flag <code>collab</code> e un provider registrato; nessun provider è presente nella build. Il sync resta quello di D-04 e A-05 (<code>Specifications.md:70</code>, <code>:559</code>): sync + merge, garantito per i soli <code>.md</code>. Accendere la collaborazione in tempo reale <strong>devia da A-05</strong> e richiede un ADR e un server futuri. Dettagli, doppio cancello e test in <a href="./0050-ai-inattiva-e-collab-spento.html">ADR-0050</a>.</p><h3 id="_11-consegna" tabindex="-1">11. Consegna <a class="header-anchor" href="#_11-consegna" aria-label="Permalink to &quot;11. Consegna&quot;">​</a></h3><p>Onde M16 in <code>docs/roadmap.md</code> (A-W0…A-W9). Lo spike A-W0 ha criteri go/no-go misurabili (blocchi forzati sporchi con <code>extract()</code> e HTML di Reading identici, località a righe ≥ 95%, dieci giri idempotenti, nessun blocco sporco senza input, bundle, CSP, accessibilità del chrome di Crepe, hotkey nei contesti annidati, montaggio in jsdom, IME su WKWebView): un no-go su fedeltà, località, assenza di scritture spontanee o CSP ferma l&#39;intervento. <strong>Esito dello spike (eseguito il 2026-11-10): alla lettera del piano è un NO-GO</strong>, perché i criteri 1, 2 e 5 falliscono (4 e 6 passano con una configurazione precisa); la decisione di procedere o fermarsi spetta all&#39;owner (dettagli in «Verificato e non»). Dopo lo spike le onde A-W3…A-W7 sono state eseguite e le condizioni per il GO sono tracciate in §12.</p><p><strong>Stato al 2026-11-12: A-W0…A-W7 fatte, A-W9 fatta; A-W8 (cancello di parità) eseguita solo nella parte automatica.</strong> Decisione dell&#39;owner del 2026-11-12: Milkdown diventa l&#39;unico motore Live e il predefinito <strong>senza attendere le prove manuali di A-W8</strong> (IME, spellcheck e lettori di schermo su WKWebView, WebView2 e WebKitGTK; incolla da app esterne; note reali grandi), che restano <strong>da fare</strong> e non sono passate. Il verdetto Pass del cancello non è stato dato: l&#39;ADR è accettato per decisione dell&#39;owner, non perché il cancello sia passato. Ogni build, rilasciata o no, ha Live su Milkdown; l&#39;interruttore <code>MEMOBRAIN_LIVE_ENGINE</code> e il CodeMirror Live Preview non esistono più (§12, «Esito di A-W9»). Prima del 2026-11-12 lo stato era: A-W0…A-W7 fatte, A-W8 e A-W9 da fare, motore dietro un interruttore spento.</p><h3 id="_12-decisioni-prese-durante-l-implementazione-a-w3-a-w9" tabindex="-1">12. Decisioni prese durante l&#39;implementazione (A-W3…A-W9) <a class="header-anchor" href="#_12-decisioni-prese-durante-l-implementazione-a-w3-a-w9" aria-label="Permalink to &quot;12. Decisioni prese durante l&#39;implementazione (A-W3…A-W9)&quot;">​</a></h3><p>Fissano ciò che nelle sezioni precedenti era «da decidere in A-Wn» o che l&#39;implementazione ha corretto.</p><ul><li><p><strong>Interruttore di build come plugin di risoluzione (rimosso in A-W9).</strong> Fino ad A-W8 <code>liveEngine</code> (<code>packages/workbench/build/esbuild.mjs</code>) risolveva <code>editor/NoteEditor</code> in <code>NoteEditor.live.tsx</code> con <code>MEMOBRAIN_LIVE_ENGINE=milkdown</code>; non era un <code>define</code>, perché con un <code>define</code> l&#39;import statico di <code>Editor</code> avrebbe tenuto CodeMirror nell&#39;entry e il bundle iniziale sarebbe salito a 2022 kB. Dal 2026-11-12 il plugin non c&#39;è più né in <code>esbuild.mjs</code> del workbench né negli script di build del desktop e del web: <code>NoteEditor.tsx</code> importa con <code>import()</code> sia <code>live/MilkdownEditor</code> sia <code>source/SourceEditor</code>, così nessuno dei due è nell&#39;entry. Resta la ragione per cui anche CodeMirror è un chunk lazy: i moduli che condivide con Milkdown (pacchetti del linguaggio e della vista, serializzatore Markdown) altrimenti sarebbero nell&#39;entry per entrambi.</p></li><li><p><strong>Budget rispettato senza alzare nessun limite</strong> (condizione 3 dello spike risolta tagliando l&#39;entry, non alzando i limiti). Misure dell&#39;implementazione fino ad A-W8, con l&#39;interruttore (le misure di A-W9, senza interruttore, sono in «Esito di A-W9»), in kB (iniziale/totale; limiti desktop 2000/23000, web workbench 2500/23000):</p><table tabindex="0"><thead><tr><th>Build</th><th>Interruttore spento</th><th>Acceso</th><th>Acceso con <code>MEMOBRAIN_AI=1</code></th></tr></thead><tbody><tr><td>desktop</td><td>1992/15998</td><td>1375/18300</td><td>1375/18300</td></tr><tr><td>web workbench</td><td>2492/14041</td><td>1916/16346</td><td>1916/16346</td></tr></tbody></table><p>Con <code>MEMOBRAIN_COLLAB=1</code> il totale cresce di circa 107 kB (desktop 18399, web 16389: chunk <code>collab-*.js</code> da 109 kB). Console web 698/698 (limite 700/1000); core WebAssembly 7099 kB gzip su 8192. <strong>Il margine sull&#39;entry spenta era di 8 kB</strong> (1992 su 2000 sul desktop, 2492 su 2500 sul web), contro i 21 kB di partenza condivisi con <a href="./0051-wails-v3.html">ADR-0051</a>: il runtime di Wails v3 sta in un chunk a parte (import dinamico di <code>wailsHost</code>), quindi non pesa sull&#39;entry. Con A-W9 l&#39;entry è 1376 kB sul desktop e 1925 sul web (margine circa 624 e 575 kB): vedi «Esito di A-W9».</p></li><li><p><strong>Caricatore del CSS dei chunk lazy</strong> (<code>linkLazyStyles</code>, <code>packages/workbench/build/esbuild.mjs</code>). Collega il foglio di un chunk solo se i suoi file non sono già nel foglio di ogni pagina che raggiunge il chunk (calcolato dal metafile). Fino ad A-W8, nella build predefinita collegava 0 fogli e ne saltava 7 (336 kB): esbuild mette già nel <code>main.css</code> il CSS dei moduli importati dinamicamente (ogni regola dei fogli lazy è presente verbatim, tranne un <code>@charset</code>). Quindi <strong>non cambiava l&#39;aspetto della build predefinita</strong> (la ipotesi dello spike che i CSS lazy non fossero caricati era sbagliata: lo erano, dentro <code>main.css</code>); il caricatore è una rete di sicurezza che si attiva solo se un foglio ha file assenti dalla pagina, e con l&#39;interruttore acceso saltava 9 fogli (395,6 kB); dopo A-W9 c&#39;è un solo caso, quello di prima con l&#39;interruttore acceso (9 fogli saltati, 0 collegati). Sul web l&#39;integrità (SRI) del CSS lazy è incorporata nel chunk.</p></li><li><p><strong>Twemoji locale con attribuzione.</strong> Le immagini vengono da <code>@discordapp/twemoji@14.1.2</code> (devDependency, pin esatto; licenza dichiarata «MIT AND CC-BY-4.0»; stessa versione Unicode del parser; il pacchetto npm <code>twemoji</code> non contiene SVG, e <code>@twemoji/svg</code> si dichiara solo MIT). <code>copyTwemojiAssets</code> copia 3689 SVG (circa 8,6 MB, 16,7 MB su disco) in <code>dist/emoji/svg/</code> e scrive <code>emoji/ATTRIBUTION.txt</code>; fino ad A-W8 lo faceva solo con l&#39;interruttore acceso, da A-W9 <strong>in ogni build</strong> (desktop e web); le SVG non sono output di esbuild e non contano nel budget, ma pesano dentro i binari <code>go:embed</code>. Il chunk <code>emoji-*.js</code> (262 kB) è lazy davvero. La CC-BY 4.0 chiede un&#39;attribuzione. <strong>Da A-W9 sta in tre posti:</strong> in <code>emoji/ATTRIBUTION.txt</code>, accanto alle immagini (scritto da <code>copyTwemojiAssets</code>, con la licenza del pacchetto); nelle impostazioni, sezione «Informazioni», riga «Licenze» (chiavi <code>settings.licenses</code> e <code>settings.twemojiAttribution</code>, in italiano e in inglese: grafica Twemoji, Copyright Twitter, Inc. e altri collaboratori, licenza CC-BY 4.0, usata senza modifiche); e nel README, sezione «Attribuzioni». Il commento del sorgente <code>chunks/emoji.ts</code> non basta: la minificazione non lo spedisce, e il commento di <code>copyTwemojiAssets</code> è stato corretto in W8 e aggiornato in A-W9. La condizione posta prima di accendere l&#39;interruttore (la riga in «Informazioni» o nel README) è soddisfatta. Il servizio di <code>/emoji/*</code> dal binario cloud e da Wails reale non è verificato (la CSP <code>img-src &#39;self&#39;</code> lo consente).</p></li><li><p><strong>Soglie <code>LIVE_MAX</code></strong> (<code>editor/live/limits.ts</code>): 250.000 caratteri, 3.000 blocchi, 20.000 caratteri per il blocco più lungo, 150 code block. Misurate sull&#39;editor montato in jsdom: 3.000 blocchi aprono in circa 1,2 s, una tabella da 500 righe costa 110 ms per modifica; un browser è più veloce sul DOM, le proporzioni restano.</p></li><li><p><strong>Strato di conservazione.</strong> Un blocco resta <code>raw</code> se, riscritto da solo e nel contesto dei vicini, non dà lo stesso albero Markdown e lo stesso <code>extract()</code> (gate di stabilità: senza, C1 era al 98,5%). Un file con EOL misto (<code>mixed-eol</code>) o che Live non restituisce identico (<code>identity</code>) si apre in Source con avviso, senza normalizzare. Un mark creato da editing prende il delimitatore del file (<code>*</code> o <code>_</code>). La busta toglie il BOM prima di <code>splitFrontmatter</code>; un secondo BOM resta nel corpo, come fa l&#39;indicizzatore; <code>splitInserted</code> toglie il BOM del frammento inserito (un template di Windows con BOM e frontmatter); <code>guardBom</code> mette una riga vuota dopo il BOM quando la prima riga diventerebbe una fence.</p></li><li><p><strong>Reload esterno e finestra di caricamento.</strong> Se lo strato rifiuta un reload esterno, Live non resta aperto col testo superato: compare l&#39;avviso e la nota passa a Source col testo nuovo, senza riscrivere quello vecchio (<code>edited=false</code>; versione passata dal figlio). Mentre Live carica (<code>suspended=&#39;wait&#39;</code>) il CodeMirror è in sola lettura, anche per i comandi e la toolbar (filtro di transazione): ciò che si digita in quella finestra è scartato, non salvato.</p></li><li><p><strong>Cosa non si usa di Milkdown.</strong> <code>plugin-automd</code> (serializza e riparsa l&#39;intero blocco a ogni tasto e rompe nodi OFM; le sue conversioni sono coperte dalle input rule, <code>[t](u)</code> compreso), <code>plugin-highlight</code> (inapplicabile ai code block di Crepe: i colori vengono dal chunk dei linguaggi, <code>@codemirror/language-data</code>), <code>prosemirror-search</code> (non installato: la ricerca è propria, circa 250 righe), la TopBar di Crepe (spenta), <code>blockEdit</code> di Crepe (maniglia e menu slash propri: vedi «Alternative considerate») e i provider LLM di Crepe; l&#39;uploader di Crepe è sostituito da <code>saveAttachment</code> (l&#39;allegato si salva nel vault e si scrive l&#39;embed, mai un URL <code>blob:</code>). <code>trailingConfig.shouldAppend</code> è spento e <code>tablePipeAlign</code> è <code>false</code> (<code>live/kit.ts</code>).</p></li><li><p><strong>Conformance.</strong> <code>packages/workbench/src/test/conformance.test.ts</code> registra anche l&#39;invariante di escape (B2) e i criteri C1–C4 del cancello A, così <code>task conformance</code> li esegue senza toccare <code>Taskfile.yml</code>; <code>yarn workspace @memobrain/workbench run live:metrics</code> ne stampa i numeri. La suite di contratto è asincrona e ha l&#39;opzione <code>lineOriented</code>: 45 casi legati alle righe di sorgente sono saltati per Milkdown e coperti da test propri.</p></li><li><p><strong>AI e collaborazione.</strong> Doppio cancello e provider: <a href="./0050-ai-inattiva-e-collab-spento.html">ADR-0050</a>.</p></li></ul><h2 id="alternative-considerate" tabindex="-1">Alternative considerate <a class="header-anchor" href="#alternative-considerate" aria-label="Permalink to &quot;Alternative considerate&quot;">​</a></h2><ul><li><strong>Playground di Milkdown (doppio editor sincronizzato, <code>replaceAll</code> a ogni cambio).</strong> Scartata: due fonti di verità e due cronologie, riscrittura totale del documento a ogni modifica, incompatibile con <code>Specifications.md:1084</code>.</li><li><strong>Sole opzioni globali di <code>remark-stringify</code>.</strong> Scartata: non valgono per nodo, non coprono escape, righe vuote né CRLF; i blocchi non toccati verrebbero comunque riscritti.</li><li><strong>Mappare gli intervalli con <code>tr.mapping</code> invece dell&#39;identità dei nodi.</strong> Scartata: più codice, perde la fedeltà dopo un undo, duplica gli intervalli con split e incolla (resta come ripiego se lo spike mostrasse che ProseMirror non conserva l&#39;identità dei sottoalberi non toccati).</li><li><strong>Estensioni micromark per ogni costrutto OFM (quarta implementazione).</strong> Scartata: precedenze CommonMark diverse da quelle dell&#39;indice. <strong>Scansione per nodo <code>text</code></strong>: scartata, rompe le regole di contesto (in <code>**a**#b</code> il frammento <code>#b</code> diventerebbe un tag).</li><li><strong>TopBar di Crepe al posto di <code>EditorToolbar</code>.</strong> Scartata finché non ha nomi accessibili, i18n e undo/redo (pulsanti solo icona, nessun <code>role=&quot;toolbar&quot;</code>): romperebbe <code>editor-toolbar.spec.ts</code>, axe <code>button-name</code> e l&#39;i18n. Resta scartata dopo M16-UX1, che accende invece la barra flottante sulla selezione.</li><li><strong>Funzione <code>blockEdit</code> di Crepe per maniglia e menu slash.</strong> Scartata (M16-UX1): porta un menu slash proprio, in Vue e senza traduzione, con regole diverse da quelle di Source, e una maniglia senza nomi per i lettori di schermo. La maniglia è costruita sul plugin dei blocchi di Milkdown (<code>@milkdown/kit/plugin/block</code>), con il markup di quella di Crepe, in DOM semplice e con i nomi; il menu resta il popup dell&#39;applicazione.</li><li><strong>Provider LLM pronti di Crepe, <code>setReadonly</code> di Crepe e nodi upstream non sovrascritti.</strong> Scartati: i provider chiamano la rete dal frontend, <code>setReadonly</code> toglie il focus, i nodi riscrivono il contenuto.</li><li><strong>Interruttore <code>liveEngine</code> in <code>.memobrain/editor.json</code>.</strong> Scartata: finirebbe nel vault del singolo utente. Si è usato per un periodo un interruttore di build ed e2e (<code>MEMOBRAIN_LIVE_ENGINE</code>), rimosso in A-W9 con la decisione dell&#39;owner di rendere Milkdown l&#39;unico motore.</li><li><strong>Lasciare Live su CodeMirror.</strong> Scartata dall&#39;utente: la richiesta è esplicita; l&#39;architettura di ADR-0004 resta per Source.</li></ul><h2 id="conseguenze" tabindex="-1">Conseguenze <a class="header-anchor" href="#conseguenze" aria-label="Permalink to &quot;Conseguenze&quot;">​</a></h2><ul><li><strong>Positive:</strong> WYSIWYG per Live, le feature di Crepe che decidono resa e scrittura (code block, liste e task, tabelle, immagini, math, cursore di trascinamento) e il plugin emoji senza reimplementarle (la barra del documento, il popup slash, la maniglia dei blocchi e la ricerca sono dell&#39;applicazione, §12; la barra sulla selezione, il tooltip dei link e il segnaposto sono di Crepe, con nomi, icone e scorciatoie dell&#39;applicazione); i <code>.md</code> non toccati restano byte-identici; un file CRLF non si converte più in LF per i blocchi non modificati; le regole OFM nascono da un&#39;unica sorgente (<code>scanInline</code>); l&#39;editor diventa testabile con una suite di contratto su due motori.</li><li><strong>Negative:</strong> un terzo parser da mantenere in conformance; un blocco modificato può essere riscritto in forma diversa (marcatore, escape, indentazione), con hunk più larghi nel diff3 — mitigato da granularità al secondo livello, stile dedotto e test di località bloccante; ProseMirror non virtualizza il DOM, quindi servono la soglia <code>LIVE_MAX</code> e il ripiego su Source; dipendenze nuove (Milkdown, Vue, yjs, twemoji) con pin esatti; le deviazioni della §9 sono regressioni accettate per chi usava Live con quelle funzioni, e da A-W9 riguardano tutti gli utenti, senza un motore di ripiego; il peso dei chunk lazy di Live si paga al primo Live aperto.</li><li><strong>Debito:</strong> la ricerca di Live è propria (circa 250 righe da mantenere, perché <code>prosemirror-search</code> è archiviato e non si usa); bug aperti upstream sugli autolink (issue 2349 di Milkdown); le API del builder e della TopBar di Crepe sono instabili.</li><li><strong>Da aggiornare dopo l&#39;accettazione (2026-11-12):</strong> ADR-0004 (stato: superata in parte da ADR-0049, fatto in A-W9), ADR-0005 (motivazione di <code>style-src &#39;unsafe-inline&#39;</code>), ADR-0020 e ADR-0025 (chunk e budget), ADR-0048 (transazioni → <code>SourceEdit</code>), <code>docs/adr/README.md</code>, <code>shared/parity/features.yaml</code> (<code>editor.modes</code> <code>:1227</code>, <code>editor.formatting</code> <code>:1192</code>, <code>editor.links</code> <code>:1242</code> e nuove voci), <code>docs/web-workbench-parity.md</code>, guida utente, CHANGELOG. <code>Specifications.md</code> va aggiornato dall&#39;owner nei punti elencati sopra.</li></ul><h2 id="verificato-e-non" tabindex="-1">Verificato e non <a class="header-anchor" href="#verificato-e-non" aria-label="Permalink to &quot;Verificato e non&quot;">​</a></h2><p><strong>Nota (2026-11-12).</strong> Le sezioni fino a «Andamento della caccia differenziale» sono il registro di ciò che è stato misurato <strong>con l&#39;interruttore <code>MEMOBRAIN_LIVE_ENGINE</code></strong>, rimosso in A-W9: «interruttore spento» vuol dire il CodeMirror Live Preview, che non esiste più, e «acceso» il Live di Milkdown di oggi. Restano come storico e non si riscrivono; lo stato di oggi è in «Esito di A-W9».</p><p><strong>Verificato sul repository (2026-11-10, sul commit <code>bd9efc3</code>, prima dell&#39;inizio delle onde; i numeri di riga possono spostarsi):</strong> <code>editor/registry.ts:5-27</code> espone <code>EditorView</code>; <code>useNoteDocument.ts:27</code> accetta un getter; <code>extract.ts:230-289</code> e <code>:341-423</code> come descritti; le tre regex in <code>livePreview.ts:43-50</code>; <code>Taskfile.yml:222</code> esegue <code>conformance.test.ts</code> se esiste, e oggi non esiste; budget in <code>esbuild.mjs</code> (desktop 2000/23000, web 2500/23000); CSP di produzione senza <code>unsafe-eval</code> e con <code>frame-src &#39;none&#39;</code>; <code>importWithRetry</code> in <code>ui/lazyView.ts</code>; i numeri di riga dello spec citati nella tabella.</p><p><strong>Riprovato sul pin 7.23.0 dallo spike A-W0 (2026-11-10):</strong> image-block, emoji e Latex di Crepe riscrivono davvero il contenuto; la TopBar di stock non ha nomi accessibili (14 pulsanti su 15 senza nome, axe <code>button-name</code>, critico) né undo/redo; <code>plugin-highlight</code> non si applica ai code block di Crepe. <strong>Non riprovati:</strong> <code>setReadonly</code> con <code>editable: () =&gt; false</code> e <code>plugin-listener</code> che serializza tutto (restano letti sul ramo <code>main</code>: da ricontrollare in A-W4).</p><h3 id="esito-dello-spike-a-w0-milkdown-crepe-7-23-0-criterio-per-criterio" tabindex="-1">Esito dello spike A-W0 (Milkdown/Crepe 7.23.0), criterio per criterio <a class="header-anchor" href="#esito-dello-spike-a-w0-milkdown-crepe-7-23-0-criterio-per-criterio" aria-label="Permalink to &quot;Esito dello spike A-W0 (Milkdown/Crepe 7.23.0), criterio per criterio&quot;">​</a></h3><p>Lo spike è un ramo usa e getta (non unito): corpus di 914 file (70 fixture, 3 file del seme demo, 146 varianti CRLF/BOM, 652 esempi CommonMark 0.31.2, 43 casi GFM/OFM scritti a mano). Nelle misure 1 e 2 «prototipo» = busta + tabella dei blocchi + prototipo OFM, senza <code>&lt;br /&gt;</code> per i paragrafi vuoti.</p><table tabindex="0"><thead><tr><th>#</th><th>Esito</th><th>Misure</th></tr></thead><tbody><tr><td>1</td><td><strong>fallisce</strong></td><td>Con tutti i blocchi sporchi, <code>extract()</code> uguale su 797/914 (87%) e HTML di Reading uguale su 846/914 (93%); senza OFM 71% e 91%; sui 116 file non avversari <code>extract</code> uguale al 95%. Cause residue: info string del fence persa, riferimenti di link risolti in inline, entità decodificate, autolink riscritti, pipe nelle tabelle. Strato di conservazione e prototipo OFM erano entrambi rozzi</td></tr><tr><td>2</td><td><strong>fallisce</strong> sul totale, passa su un sottoinsieme</td><td>Un carattere inserito dà ≤1 riga nell&#39;83,9% di 4283 casi (soglia 95%); 87% sui file reali; 99,1% (1089/1099) senza i blocchi «raw» (commenti e math multi-riga, tabelle, codice indentato, setext). Spunta del task in lista annidata da 200 voci: 1 riga in 5 varianti su 5 (passa)</td></tr><tr><td>3</td><td><strong>passa</strong></td><td>Dieci giri idempotenti in 910/914; i fallimenti sono solo esempi CommonMark patologici. Issue 2349 non riprodotta, ma gli autolink vengono riscritti (<code>&lt;https://…&gt;</code>; <code>www.x</code> diventa link con <code>http://</code>)</td></tr><tr><td>4</td><td><strong>fallisce</strong> di default, passa con configurazione</td><td><code>trailing</code> aggiunge un paragrafo vuoto alla prima transazione, anche solo di selezione, nel 36,9% dei documenti; con <code>trailingConfig.shouldAppend = () =&gt; false</code> il cambio è 0/236 per selezione, hover e tooltip. Il plugin degli id dei heading cambia <code>heading.id</code> in 49/236 documenti: la tabella dei blocchi va costruita sul documento dopo il caricamento. Hover e fold reali non verificati</td></tr><tr><td>5</td><td><strong>fallisce</strong></td><td>Bundle iniziale desktop da 1981 kB (baseline misurata) a 2012 (limite 2000; totale 18402/23000); web da 2482 a 2565 (limite 2500; totale 16509/23000). Il tree-shaking porta nell&#39;iniziale i moduli condivisi con i chunk lazy (+31 kB: <code>mdast-util-to-markdown</code>, <code>@codemirror/*</code>) e, sul web, +51 kB di CSS di Crepe. Chunk lazy: editor 303 kB, linguaggi 17, emoji 262, AI 35, collab 106. Il CSS di Crepe (76 kB) non viene collegato dal desktop (<code>esbuild.mjs:39-41</code> linka solo l&#39;entry; 9 CSS lazy su 10 non sono nell&#39;HTML, compreso <code>DrawingEditor</code>, 307 kB: non verificato se oggi funziona). I <code>define</code> di Vue non hanno effetto utile (6 kB totali, 0 sull&#39;iniziale)</td></tr><tr><td>6</td><td><strong>fallisce</strong> di default, passa con configurazione</td><td>Con la CSP di <code>csp_prod.go</code>, 0 violazioni al mount. Digitando <code>:smile:</code> Twemoji carica da <code>cdn.jsdelivr.net</code> e viola <code>img-src</code>; con <code>base</code> locale 0 violazioni e 0 richieste esterne (servono gli svg in locale: <code>@twemoji/svg</code>, 8,1 MB, 3723 file). Zero <code>eval</code>/<code>new Function</code> nei chunk Milkdown (quello già presente in <code>chunk-QBD644DD</code> è identico nella baseline); la rete in Crepe sta solo in <code>llm-providers/*</code></td></tr><tr><td>7</td><td><strong>passa</strong> con configurazione, senza patch</td><td>TopBar di stock: 14 pulsanti su 15 senza nome (axe <code>button-name</code>, critico), niente undo/redo, titoli di gruppo in inglese. Con icone SVG con <code>aria-label</code>, <code>headingOptions</code> tradotte e <code>buildTopBar</code> per undo/redo: 0 violazioni axe sulla TopBar, 17 pulsanti. Mancano <code>role=toolbar</code> e navigazione a frecce. Restano nel contenuto <code>aria-input-field-name</code> ×3, <code>button-name</code> ×2 (pulsanti «+» delle tabelle), <code>list</code>/<code>listitem</code></td></tr><tr><td>8</td><td><strong>passa</strong> (solo meccanica DOM)</td><td>Un listener <code>keydown</code> in cattura sulla radice vede i tasti dal code block annidato e dalla cella di tabella; tooltip, block-handle e TopBar stanno dentro la radice. CM chiama <code>preventDefault</code> su Ctrl+B e Ctrl+K: il fallback globale (<code>App.tsx:208-216</code>) non li vedrebbe. Il cablaggio a <code>commandForEvent</code> non è provato</td></tr><tr><td>9</td><td><strong>passa</strong> con shim</td><td>Crepe si monta in jsdom (236 editor, 0 errori) con due shim da mettere in <code>src/test/setup.ts</code>: <code>IntersectionObserver</code> e <code>Range.getClientRects</code>/<code>getBoundingClientRect</code>. L&#39;attributo <code>aria-label=&quot;Note editor&quot;</code> richiesto da <code>App.test.tsx:74</code> va aggiunto a <code>view.dom</code>. Istanza unica di <code>@codemirror/state</code>, <code>@codemirror/view</code>, <code>katex</code> e <code>vue</code> (metafile)</td></tr><tr><td>10</td><td><strong>non verificabile qui</strong></td><td>Nessun IME né WKWebView disponibili</td></tr></tbody></table><p><strong>Lettura del risultato.</strong> Alla lettera del piano i criteri 1, 2 e 5 falliscono e i criteri 4 e 6 passano solo con la configurazione indicata: è un <strong>NO-GO</strong>, e la decisione di procedere spetta all&#39;owner. Lo spike stesso raccomanda «GO con condizioni» (elencate sotto), perché i rimedi sono dimostrati solo in parte. I rimedi di 4, 6 e in parte 5 sono già verificati; per 1 e 2 sono dimostrati solo in parte (i blocchi «raw» portano la località al 99,1%).</p><p><strong>Nodi upstream che riscrivono</strong> (tutti sovrascrivibili con <code>extendSchema</code>): image-block (<code>![schema](a.png)</code> diventa <code>![1.00](a.png)</code>, <code>alt|300</code> va perso; con l&#39;override l&#39;alt resta esatto in 5 casi su 5); emoji (<code>a:b:c</code> diventa <code>a🅱️c</code>; senza <code>remark-emoji</code> il testo resta esatto in 3 casi su 3); Latex di Crepe (<code>```latex</code> diventa <code>$$</code>; con l&#39;override resta esatto, salvo una fence <code>```LaTeX</code> maiuscola che collide con il marcatore); wikilink e tag di stock (<code>[[x]]</code> diventa <code>\\[\\[x]]</code>, <code>\\#tag</code> perde l&#39;escape e diventa un tag vero, <code>[!note]</code> e <code>^[n]</code> si rompono: il prototipo OFM li conserva tutti).</p><p><strong>Altri esiti.</strong> <code>plugin-highlight</code> non si applica ai code block di Crepe (il parser è chiamato ma il NodeView CM non rende le decorazioni): va scartato, i colori vengono dal chunk dei linguaggi. Core WASM a 7102/8192 kB gzip. Bug upstream: <code>:smile:</code> digitato in una cella di tabella lancia <code>RangeError: Applying a mismatched transaction</code>. Prestazioni su una nota da 146 kB: apertura 300 ms, serializzazione completa 66 ms, composizione con un blocco sporco 0,2 ms.</p><p><strong>Condizioni per un eventuale GO.</strong></p><ol><li>A-W3 deve avere blocchi raw (commenti, math, tabelle, setext, codice indentato, riferimenti di link, info string del fence) e rimisurare; soglia proposta: 100% di <code>extract</code> e HTML uguali sul corpus non avversario e ≥95% a ≤1 riga.</li><li><code>trailingConfig.shouldAppend</code> spento, tabella costruita sul documento dopo il caricamento, <code>tablePipeAlign: false</code>, niente <code>&lt;br /&gt;</code> per i paragrafi vuoti, <code>remark-emoji</code> escluso, override di image-block e Latex, Twemoji locale.</li><li>Budget: o si alza esplicitamente (desktop +12 kB, web +65 kB) o si taglia l&#39;entry; il CSS lazy richiede un caricatore per chunk.</li><li>TopBar solo con icone etichettate e <code>role=toolbar</code> impostato dall&#39;esterno.</li><li>Prova IME su WKWebView prima di A-W8.</li></ol><p><strong>Ancora da provare</strong> (non coperto dallo spike): IME, spellcheck e accessibilità sulle tre WebView (WKWebView, WebView2, WebKitGTK; prova manuale in A-W8); hover e fold reali; il cablaggio delle hotkey a <code>commandForEvent</code>; il bundle di produzione con gli svg Twemoji locali; <code>task ci</code>; <code>LIVE_MAX</code> su documenti grandi (blocco sporco da 500 voci, tabella da 2000 righe); il folding non-heading e il riordino liste in Live (§9).</p><h3 id="stato-dopo-a-w7-2026-11-11" tabindex="-1">Stato dopo A-W7 (2026-11-11) <a class="header-anchor" href="#stato-dopo-a-w7-2026-11-11" aria-label="Permalink to &quot;Stato dopo A-W7 (2026-11-11)&quot;">​</a></h3><p>Il paragrafo precedente («Dopo A-W2…») è superato: oggi esistono la busta, la tabella dei blocchi, la composizione, la grammatica OFM, <code>MilkdownEditor</code> con viste, input e cornice, i cancelli di AI e collaborazione e la suite di contratto sui due motori. Il tutto è raggiungibile solo con l&#39;interruttore di build (§12).</p><p><strong>Cancello A, rieseguito il 2026-11-11</strong> con <code>yarn workspace @memobrain/workbench run live:metrics</code> (corpus di 1075 file: fixture di <code>shared/conformance/markdown</code>, <code>demo/</code>, <code>cases/</code>, varianti CRLF e BOM, esempi CommonMark 0.31.2; 7 esempi esclusi come avversari, con motivo in <code>testing/adversarial.ts</code>):</p><table tabindex="0"><thead><tr><th>Criterio</th><th>Esito sul corpus non avversario</th></tr></thead><tbody><tr><td>C1</td><td><code>extract()</code> e HTML di Reading identici in 1074/1074 (100%); con le posizioni, <code>extract</code> identico in 1049; CRLF conservato in 1074</td></tr><tr><td>C1-edit</td><td>il percorso di modifica (split, inserimento, cancellazione, caratteri speciali) dà lo stesso albero, <code>extract</code> e HTML della riscrittura forzata: 35041/35041</td></tr><tr><td>C2</td><td>un carattere digitato cambia al più una riga in 4266/4267 (99,98%; resta <code>commonmark/552</code>, dove digitare crea una definizione di link e il serializzatore riscrive due righe); la spunta in una lista annidata da 200 voci cambia 1 riga (prima, centrale, ultima)</td></tr><tr><td>C3</td><td>dieci giri idempotenti: 1074/1074</td></tr><tr><td>C4</td><td>0 blocchi sporchi al caricamento, per selezione e per hover, 0 testi alterati, su 1074 file; sull&#39;intero corpus c&#39;è un solo rifiuto, <code>commonmark/215</code> (avversario)</td></tr></tbody></table><p>Blocchi <code>raw</code>: 10,46% sulle fixture, 0% nel seme demo, 8,96% nei casi scritti a mano. I criteri sono asserzioni bloccanti in <code>conformance.test.ts</code> (quindi in <code>task conformance</code>).</p><p><strong>C1-edit e caccia differenziale.</strong> Il revisore di A-W3 ha mostrato che C1 e C3 misuravano solo il percorso forzato; da allora C1-edit confronta la modifica reale con <code>forceDirty</code> e le sonde differenziali (modifiche a caso contro la riscrittura forzata) sono scese a 0 divergenze sulle forme note. Resta il <strong>residuo dichiarato</strong>: una voce di lista che contiene un commento <code>%%…%%</code> e una fence non chiusa, con un <code>%%</code> digitato altrove nella nota, fa differire Reading (13 occorrenze nello sweep <code>cmt</code> di A-W3); la riscrittura forzata chiude la fence, la modifica no. In C1-edit 76 file non sono leggibili dal parser in modalità sviluppo (asserzioni <code>devlop</code> di <code>mdast-util-gfm-task-list-item</code>) e in una sonda del revisore di A-W5 due casi su 6997 (Tab nelle varianti <code>~bom</code>) fermano un&#39;asserzione <code>devlop</code>, non presente in produzione.</p><p><strong>C4 sull&#39;editor montato.</strong> Sonda del revisore di A-W5 (non nel repository): <code>openLiveEditor</code> con le viste di Crepe in jsdom su 1074 file non avversari, dopo selezione, hover, fold totale e per blocco, ricerca, impostazioni, sola lettura e callout: 0 testi cambiati, 0 documenti cambiati, 0 <code>onChange</code>. Le sue misure di hover e fold usano eventi sintetici di jsdom: non provano un browser reale.</p><p><strong>Test e build.</strong> Suite del workbench: 155 file passati e 1 saltato, 2060 test passati e 46 saltati; <code>@memobrain/markdown</code> 201/201; Go <code>TestConformance</code>, <code>TestConformanceCRLF</code> e <code>TestParseSkipsLeadingBOM</code> verdi; <code>tsc</code> di workbench, desktop-frontend e web puliti. Build con interruttore spento, acceso e acceso con AI, tutte entro i budget (§12). e2e su mock dei binding (desktop-mock): 40 passati (<code>live-input</code>, <code>live-views</code>, <code>live-frame</code>, <code>live-ai</code>, <code>editor-find</code>, <code>editor-toolbar</code>, <code>workflows</code>, <code>status-bar</code>); gli stessi 40 sul core WebAssembly nel browser (web-core), con un <code>.wasm</code> non ricompilato nell&#39;ultimo giro. Prima di A-W8 l&#39;e2e va rifatto con il <code>.wasm</code> ricompilato.</p><p><strong>Non verificato.</strong></p><ul><li>IME, spellcheck, accessibilità con lettore di schermo (VoiceOver, NVDA) e comportamento reale su WKWebView, WebView2 e WebKitGTK: prova manuale di A-W8, sulla shell Wails v3.</li><li><code>task ci</code>, <code>task parity</code> ufficiale e <code>task e2e-matrix</code> ufficiale non eseguiti dalle catene che hanno scritto il codice; <code>node scripts/parity.mjs --check</code> aveva segnalato <code>docs/web-workbench-parity.md</code> da rigenerare a metà onda.</li><li>Un browser reale per hover e fold, e per il completamento <code>[[</code> dentro una voce di lista (in jsdom serve attendere un frame: il ripristino della selezione della lista di Crepe).</li><li>Una build con <code>MEMOBRAIN_AI=1</code> con il chunk AI realmente caricato nel browser (ADR-0050).</li><li>Il serving di <code>/emoji/*</code> dal binario cloud e da Wails reale; la CSP di produzione completa con il motore acceso.</li><li>Il comportamento con un provider di collaborazione vero e l&#39;interazione con l&#39;identità dei blocchi (ADR-0050).</li><li>Il folding con la tastiera su Mac (Cmd-Alt-[); Mod+F con un IME attivo nei campi della barra.</li><li>Il peso di <code>LIVE_MAX</code> su documenti grandi in un browser vero (le soglie sono misurate in jsdom).</li><li>Le 3 spec e2e che con Milkdown acceso falliscono per costruzione (selettori <code>.cm-*</code>, <code>[[</code> digitato senza regola, «Col 1» esatto) sono state adattate al motore (in Live <code>status-bar</code> accetta qualsiasi colonna); la colonna esatta resta provata solo su CodeMirror.</li></ul><h3 id="esito-del-cancello-a-w8-parte-automatica-2026-11-11" tabindex="-1">Esito del cancello A-W8, parte automatica (2026-11-11) <a class="header-anchor" href="#esito-del-cancello-a-w8-parte-automatica-2026-11-11" aria-label="Permalink to &quot;Esito del cancello A-W8, parte automatica (2026-11-11)&quot;">​</a></h3><p>Condizioni: Mac in alimentazione di rete, carico macchina 11–55 per altri agenti in esecuzione (le misure di prestazione sono indicative), solo Chromium headless contro i mock dei binding e il core WebAssembly. <strong>Nessuna WebView reale e nessuna shell Wails v3: NON VERIFICATO.</strong> Il verdetto Pass del cancello <strong>non è dato</strong>: l&#39;accessibilità è NON PASS e restano le prove manuali.</p><p><strong>Verificato</strong></p><ul><li><strong>Matrice e2e</strong> (<code>task e2e-matrix</code>): con <code>MEMOBRAIN_LIVE_ENGINE=milkdown</code> 313 passati, 0 falliti, 13 saltati (11,6 min); con l&#39;interruttore spento 249 passati, 0 falliti, 77 saltati (10,8 min). I 13 saltati in comune sono <code>drawing-export</code> (4), <code>drawing-wp5</code> (2), <code>graph-bench</code> (2), <code>open-by-type</code> (1), <code>ui-perf</code> (4); gli altri 64 con l&#39;interruttore spento sono gli spec <code>live-*</code>. Il primo giro con l&#39;interruttore spento non è attendibile (69 <code>ENOENT</code>: la cartella dei risultati è stata cancellata da un processo concorrente); rilanciato con porte proprie (<code>E2E_MATRIX_DESKTOP_PORT</code>, <code>E2E_MATRIX_WEB_PORT</code>).</li><li><strong>Metriche</strong> (<code>yarn workspace @memobrain/workbench run live:metrics</code>, corpus di 1075 file, 9 test passati in 146 s): C1 1074/1074 (sull&#39;intero corpus 1074/1075, un rifiuto: <code>commonmark/215</code>); C1-edit 35.041/35.041; C2 4266/4267 (99,98%; <code>commonmark/552</code>), la spunta in una lista da 200 voci cambia 1 riga (prima, centrale, ultima); C3 1074/1074; C4 0 sporchi al caricamento, per selezione e per hover. Fuzz rieseguito: 4 semi casuali 17 divergenze su circa 88.000 modifiche (99,98%), identiche al cancello A; 3 semi «reali» 0 su 65.554. Nessun peggioramento.</li><li><strong>Budget</strong> (build <code>build</code>): desktop spento 1992/15998 kB (limiti 2000/23000), acceso 1375/18304; web workbench spento 2492/14041 (limiti 2500/23000), acceso 1916/16350; console 698 su 700; core WebAssembly 7102 kB gzip su 8192; sqlite 398 su 1536.</li><li><strong>Soglia <code>LIVE_MAX</code>:</strong> le note da 300 kB e da 1 MB si aprono in Source con l&#39;avviso «more than 250,000 characters»; quella da 160 kB a blocchi con «more than 3,000 blocks». La digitazione arriva a destinazione in tutte le celle misurate.</li><li><strong>Rete e CSP:</strong> <code>workbench-csp</code> 5/5 (verifica solo l&#39;avvio, con la build E2E accesa e l&#39;handler di produzione). Su una nota con emoji, immagini locali e remote, html, code, math e mermaid, e con picker emoji, slash, find e toolbar, l&#39;unica richiesta fuori dall&#39;origine è <code>https://example.com/remote.png</code>, bloccata da <code>img-src &#39;self&#39; data: blob:</code> come con CodeMirror; l&#39;emoji arriva da <code>/emoji/svg/1f600.svg</code>; zero errori di pagina. <code>live-ai</code> e <code>live-collab</code> passano nella matrice accesa.</li><li><strong><code>fileChanges.perf</code>:</strong> 3/3 passati (gira in jsdom, non dipende dal motore).</li></ul><p><strong>Prestazioni</strong> (spec scratch, due ripetizioni per cella; il campionamento a due frame quantizza i valori a circa 16 e 33 ms; con l&#39;interruttore spento tutte le note si aprono in Live di CodeMirror, con Milkdown le note oltre la soglia si aprono in Source):</p><table tabindex="0"><thead><tr><th>Nota</th><th>Apertura CodeMirror</th><th>Apertura Milkdown</th><th>p50 / p95 CodeMirror (ms)</th><th>p50 / p95 Milkdown (ms)</th></tr></thead><tbody><tr><td>5 kB</td><td>0,15–0,18 s</td><td>0,93–0,96 s</td><td>25 / 33</td><td>17–19 / 31–32</td></tr><tr><td>200 kB</td><td>0,23–0,24 s</td><td>2,53–2,56 s</td><td>26–27 / 32–34</td><td>17–19 / 31–33</td></tr><tr><td>130 kB, circa 2.900 blocchi</td><td>0,14 s</td><td>2,07–2,12 s</td><td>26 / 33</td><td>17 / 31</td></tr><tr><td>300 kB, 160 kB a blocchi, 1 MB</td><td>0,14–0,54 s</td><td>Source con avviso, 0,44–0,47 s</td><td>25–27 / 32–34</td><td>26 / 33</td></tr></tbody></table><p>La latenza di digitazione è pari o migliore di CodeMirror. <strong>L&#39;apertura con Milkdown costa circa 0,8 s di avvio a freddo (chunk lazy) e circa 10 volte CodeMirror a 200 kB (2,5 s).</strong> I commenti di <code>editor/live/limits.ts</code> dichiarano soglie che tengono l&#39;apertura «near a second» (misura di jsdom, §12): da rivalutare le soglie, o da rimisurare a macchina scarica. Con <code>ui-perf.spec</code> del repository (nota da 5 kB): CodeMirror apertura 156 ms, p50 25,1, p95 32,8; Milkdown 568 ms, p50 17,1, p95 30,7.</p><p><strong>Accessibilità: NON PASS al momento della misura; corretta in W8 (vedi «Stato dopo W8»).</strong> <code>a11y.spec</code> con l&#39;interruttore acceso passa (24/24 su desktop-mock, 0 violazioni; passa anche web-core nella matrice), ma scansiona una nota vuota ed esclude <code>.cm-content</code>: non entra in una nota con liste. Scansione su una nota ricca (liste, task, callout, tabella, code, math, embed; tema chiaro e scuro), confrontata con CodeMirror ripetendo la scansione con <code>.cm-content</code> incluso (<code>QA_INCLUDE_CM=1</code>):</p><table tabindex="0"><thead><tr><th>Gravità</th><th>Regola</th><th>Elemento</th><th>Rispetto a CodeMirror</th></tr></thead><tbody><tr><td>serious</td><td><code>list</code> (4 elementi)</td><td><code>ul</code>/<code>ol</code> con <code>li</code> dentro <code>div.milkdown-list-item-block</code></td><td>nuova</td></tr><tr><td>serious</td><td><code>listitem</code></td><td><code>.milkdown-list-item-block &gt; li</code></td><td>nuova</td></tr><tr><td>serious</td><td><code>color-contrast</code> 1,36:1 (chiaro), 1,52:1 (scuro)</td><td><code>.ordered.label.milkdown-icon</code> (numeri delle liste ordinate)</td><td>nuova</td></tr><tr><td>serious</td><td><code>color-contrast</code> 4,13 chiaro / 3,07 scuro</td><td><code>span[data-ofm=&quot;tag&quot;]</code></td><td>come CodeMirror (<code>.cm-lp-tag</code>, stessi token)</td></tr><tr><td>serious</td><td><code>color-contrast</code> 3,43 scuro</td><td>wikilink e link esterni</td><td>come CodeMirror</td></tr></tbody></table><p>Milkdown risolve <code>aria-toggle-field-name</code> sulla casella dei task (CodeMirror l&#39;ha ancora); <code>scrollable-region-focusable</code> e <code>page-has-heading-one</code> sono solo in CodeMirror; best-practice sul Live di Milkdown: 0. <strong>Proposta:</strong> estendere <code>a11y.spec</code> a una nota ricca in Live senza escludere <code>.ProseMirror</code>; correggere la struttura delle liste con ruoli ARIA o un override del nodo, e il colore dell&#39;etichetta con un token <code>--crepe-*</code>, in <code>packages/workbench/src/editor/live/</code>.</p><p><strong>Caccia differenziale sull&#39;editor montato</strong> (jsdom, non nel repository). 195.642 sequenze di input utente, 181.976 delle quali hanno modificato il documento; corpus di 423 documenti (conformance, demo, cases, varianti CRLF e BOM) più i 651 esempi CommonMark non avversari; due passate con semi 1 e 2. Cinque famiglie: digitazione carattere per carattere con le input rule, tasti (Invio, Backspace, Canc, Tab, Shift+Tab), incolla di testo e HTML, altri ingressi (completamento <code>[[</code>, slash con 16 voci, casella dei task, selezioni a intervallo, undo e redo) e percorsi casuali da 4 a 12 passi. Oracoli: testo salvato contro <code>forceDirty</code>; perdita di voci di <code>extract()</code> nelle righe invariate; byte fuori dai blocchi toccati; cambio Live → Source → Live; undo e redo completi; conteggi di task e wikilink contro <code>extract()</code>.</p><ul><li><strong>Il percorso di modifica concorda ancora con la serializzazione forzata (C1-edit):</strong> 1 divergenza su 195k, un file con doppio BOM dove sbaglia la serializzazione forzata e non la modifica. Live → Source → Live non ha mai prodotto un testo diverso; l&#39;undo completo ripristina i byte originali in tutti i casi non banali; il redo diverge solo nella causa 6.</li><li><strong>Divergenze nuove, per causa.</strong> La causa 1 è quella che conta. <ol><li><strong>Task con primo paragrafo vuoto seguito da un blocco</strong> (la più seria). Input minimo <code>- [ ] a\\n- [x] b\\n</code> con il caret all&#39;inizio del testo del primo task; incolla <code>- x\\n- y</code> → <code>-\\n[ ] - x\\n - y\\n a\\n- [x] b\\n</code>; stesso effetto digitando <code>---</code>, incollando una fence di codice, <code>&gt; [!note]</code>, una tabella, <code>&lt;h1&gt;</code>, <code>&lt;ul&gt;</code> o <code>$$</code>, selezionando un intervallo che attraversa i task e premendo Invio, e dentro una citazione. La casella finisce su una riga non indentata e il task perde lo stato; il contenuto esce dalla lista; la riapertura in Live è rifiutata (<code>load Expected value to be truthy</code>) e la nota resta in Source; quando la finestra non è «sound» il compositore allarga la riscrittura e nei file CRLF i titoli intatti perdono i <code>#</code> finali (<code># Alpha #</code> → <code># Alpha</code>). Il cancello non la vede perché modifica e serializzazione forzata coincidono. Frequenza: 249 dei 275 rifiuti di riapertura e circa 300 casi <code>E:tasks</code>. Dove guardare (causa esatta non isolata): <code>fidelity/compose.ts</code>, <code>forcedBlock</code> e <code>composeContainer</code> per <code>list_item</code> con <code>checked</code>, e <code>windowIsSound</code>.</li><li><strong>Spazio iniziale prima di un nodo OFM</strong> (<code>[[a]] text</code>, <code>#tag text</code>, <code>==hi== text</code>, <code>%%c%% text</code> con quattro spazi o <code>\\t</code> all&#39;inizio): il testo scritto è <code> [[a]] text</code> (con il testo semplice scrive <code>&amp;#x20;</code>); Reading lo rende come <code>&lt;pre&gt;&lt;code&gt;</code>, <code>extract()</code> non vede link né tag, alla riapertura il blocco diventa <code>raw_block</code>.</li><li><strong><code>%%</code> o <code>$$</code> digitati nell&#39;etichetta di un wikilink</strong> (<code>see [[ab]] and [[cd]] #tag</code>, digitando <code>%%</code> dopo la <code>a</code>): il testo diventa <code>[[a%%b]]</code>, <code>extract()</code> legge 0 link (Live ne mostra 2) e il commento aperto inghiotte il resto del file; Invio nell&#39;etichetta spezza il nodo (<code>[[a]]</code> e <code>[[b]]</code>) o ne crea uno vuoto <code>[[]]</code>.</li><li><strong>Titolo che contiene un raw inline</strong> (incolla di <code>https://x.org</code> o digitazione di <code>[^1]</code> in <code>## Title</code>): il testo è corretto, ma alla riapertura il titolo diventa <code>raw_block</code> e non è più modificabile come titolo.</li><li><strong>Minore:</strong> un <code>hr</code> identico a un altro cambia marcatore (<code>---\\n\\nafter a rule\\n</code>, slash <code>/divider</code> → <code>***\\n\\nafter a rule\\n\\n---\\n</code>).</li><li><strong>Minore:</strong> il redo non riproduce la modifica nelle tabelle (selezione 4-17 di una tabella 2×2, incolla HTML <code>&lt;p&gt;a&lt;/p&gt;&lt;p&gt;b&lt;/p&gt;</code>; dopo undo e redo compare una riga vuota in più; 96 casi, tutti incolla di blocchi in una cella).</li><li><strong>Minore:</strong> le righe fratelle sono riscritte in liste con indentazione irregolare (<code>- a\\n - b\\n - c\\n</code>, esempi CommonMark 295, 310 e 312; circa 276 casi sull&#39;oracolo dei byte fuori dai blocchi toccati).</li></ol></li><li><strong>Fuori dal perimetro dell&#39;editor:</strong> <code>extract()</code> TS ignora il backtick con escape (il testo <code>\\`[[a]] #t</code> ha 0 link e 0 tag, mentre Reading li rende) e l&#39;editor scrive quell&#39;escape alla digitazione di un backtick; il parser Go è NON VERIFICATO.</li><li><strong>Oracoli scartati come rumore:</strong> titoli contati da <code>extract()</code> (vuoti o annidati), task vuoti scritti come <code>-</code>, <code>raw_inline</code> che tornano testo, slash <code>embed</code> con <code>![[]]</code> vuoto, spazi finali.</li><li><strong>Non verificato nella caccia:</strong> Backspace e Invio nativi del browser (emulati con i comandi di ProseMirror), il code block CodeMirror, il parser Go, <code>task ci</code>.</li><li><strong>Stato dopo W8 (2026-11-11).</strong> Corrette, ciascuna con un test che fallisce senza la correzione: le cause 1, 2, 3 e 4 (task con primo paragrafo vuoto seguito da un blocco, spazio iniziale prima di un nodo OFM, <code>%%</code>, <code>$$</code> e <code>[</code> nell&#39;etichetta di un wikilink, titolo con <code>[^1]</code> o URL incollato) e l&#39;accessibilità (<code>input/listSemantics.ts</code>: ruoli <code>listitem</code> e <code>none</code>, bullet e numeri <code>aria-hidden</code>; colore delle etichette sul token <code>--crepe-color-on-surface-variant</code>; caselle dei task chiamate «Task: testo»; <code>a11y.spec</code> su una nota ricca con <code>.ProseMirror</code> incluso, chiaro e scuro). La causa 5 non è un bug (<code>---</code> in prima riga con un secondo <code>---</code> sotto sarebbe frontmatter). Non corrette: la causa 6 (redo nelle tabelle) e la 7 (indentazione irregolare nelle liste), e l&#39;escape del backtick in <code>extract()</code> (Go e TS insieme). <strong>Aperti al momento di W8, chiusi in W9:</strong> la casella di un task nato da un bullet restava <code>aria-hidden</code> (<code>listSemantics.ts</code> aggiornava solo le voci senza ruolo) e un <code>%%</code> incollato nell&#39;etichetta di un wikilink apriva un commento (la guardia copriva la digitazione, non l&#39;incolla). Scelte da confermare: un task con il solo stato e altri blocchi è scritto <code>-</code>, e togliere <code>\\[^1]</code> nei titoli può cambiare la semantica se la nota ha la definizione <code>[^1]:</code>.</li></ul><p><strong>Revisione finale della Parte A (2026-11-11): Pass con riserve</strong>, nessun rilievo alto o medio. Con i tre interruttori spenti (allora) la build predefinita non conteneva Milkdown, ProseMirror, Yjs né il frontend AI (bundle entro i budget, numeri sopra; nessun file contiene <code>milkdown</code>, <code>ProseMirror</code>, <code>y-prosemirror</code>, <code>MilkdownAdapter</code>); il core WebAssembly non dipende da <code>internal/ai</code>, <code>go-keyring</code> né <code>wailsapp</code>; nessuna risoluzione esistente di <code>yarn.lock</code> è cambiata; pin esatti su <code>@milkdown/*</code> 7.23.0, <code>yjs</code>, <code>y-prosemirror</code>, <code>y-protocols</code> e <code>@discordapp/twemoji</code>; licenze 136 MIT, 1 ISC, 1 BSD-2 (Twemoji MIT e CC-BY-4.0); nessun segreto. Rilievi bassi aperti:</p><ul><li><strong>R1:</strong> nessun controllo automatico tiene Milkdown, AI e collab fuori dalle build predefinite e di rilascio (nessuno tra <code>Taskfile.yml</code>, <code>scripts/</code>, <code>release.yml</code> e <code>services/cloud/Dockerfile</code> cita <code>MEMOBRAIN_LIVE_ENGINE</code>, <code>MEMOBRAIN_AI</code>, <code>MEMOBRAIN_COLLAB</code>; il budget non coglie un chunk lazy). Correzione proposta: fallire negli script di rilascio se una delle tre variabili è impostata e un test che cerca <code>milkdown</code> nel <code>dist</code> della build predefinita. <strong>Chiuso in W8:</strong> <code>scripts/release/check-editor-switches.sh</code> (rifiuta anche <code>MEMOBRAIN_E2E</code> e <code>MEMOBRAIN_DIST</code>) e <code>scripts/release/check-dist.sh</code> (cerca Milkdown e il mock dei binding nel <code>dist</code>; <strong>cambiate in A-W9</strong>: la prima non elenca più <code>MEMOBRAIN_LIVE_ENGINE</code>, la seconda cerca <code>y-prosemirror</code> e il mock e pretende <code>assets/MilkdownEditor-*.js</code>, vedi «Esito di A-W9») girano in <code>build-desktop-bin.sh --release</code>, <code>release/build-desktop.sh --release</code> (che <code>task release-desktop</code> passa sempre), <code>task web-build</code> e nel Dockerfile del cloud.</li><li><strong>R3:</strong> le prove di <code>editor.ai</code> ed <code>editor.collab</code> in <code>shared/parity/features.yaml</code> non erano quelle del §7 di ADR-0050. Corretto il 2026-11-11: <code>editor.ai</code> ha ora anche <code>ai/wiring.test.ts</code> e <code>live-ai.spec.ts</code>, <code>editor.collab</code> i test di <code>collab/</code> (<code>collab.test.ts</code>, <code>converge.test.ts</code>, <code>wiring.test.ts</code>) e <code>live-collab.spec.ts</code>; <code>node scripts/parity.mjs</code> e <code>task parity</code> verdi.</li><li><strong>R4:</strong> il commento di <code>copyTwemojiAssets</code> in <code>packages/workbench/build/esbuild.mjs</code> dichiara un&#39;attribuzione CC-BY nel JS spedito, che la build minificata non contiene (resta solo in <code>emoji/ATTRIBUTION.txt</code>, e nel commento del sorgente <code>chunks/emoji.ts</code>, che non viene spedito): il commento è stato corretto in W8 (l&#39;attribuzione sta in <code>emoji/ATTRIBUTION.txt</code>, copiato solo con l&#39;interruttore acceso) e la riga in «Informazioni» o nel README va scritta prima di accendere l&#39;interruttore. <strong>Chiuso in A-W9:</strong> la riga «Licenze» in «Informazioni» e la sezione «Attribuzioni» del README sono scritte, e le immagini e <code>ATTRIBUTION.txt</code> sono in ogni build.</li><li><strong>R5:</strong> <code>linkLazyStyles</code> non collega mai nulla (0 fogli collegati, 7 saltati a interruttore spento e 9 a acceso) e dipende dalla cartella di lavoro (con un&#39;altra cartella la build fallisce con <code>ENOENT</code>). In W8 le build hanno avuto <code>absWorkingDir</code>; il caricatore resta come rete di sicurezza (A-W9 non l&#39;ha toccato: tenerlo o toglierlo è ancora da decidere).</li><li><strong>R2 e R6 sono documentazione</strong> e sono state corrette il 2026-11-11 (CHANGELOG per il pulsante Tabella; §7 e §12 di questo ADR; ADR-0050; roadmap, con il margine reale dell&#39;entry desktop: 8 kB, 1992 su 2000).</li></ul><h3 id="andamento-della-caccia-differenziale-a-w3-w7-w8-w9-w10-consolidamento-e-conclusione" tabindex="-1">Andamento della caccia differenziale (A-W3, W7, W8, W9, W10, consolidamento) e conclusione <a class="header-anchor" href="#andamento-della-caccia-differenziale-a-w3-w7-w8-w9-w10-consolidamento-e-conclusione" aria-label="Permalink to &quot;Andamento della caccia differenziale (A-W3, W7, W8, W9, W10, consolidamento) e conclusione&quot;">​</a></h3><p>Ogni giro ha chiuso le divergenze trovate e ne ha trovate di nuove, in sequenze meno comuni. La caccia non è esaurita: i numeri sotto dicono cosa è stato provato, non che il resto sia sano.</p><ul><li><p><strong>A-W3.</strong> Il revisore ha mostrato che C1 e C3 misuravano solo il percorso forzato; con C1-edit le sonde differenziali sono scese a 0 sulle forme note, con un residuo dichiarato (§12).</p></li><li><p><strong>W7.</strong> 195.642 sequenze: sette cause, di cui la 1 seria (task con primo paragrafo vuoto seguito da un blocco).</p></li><li><p><strong>W8.</strong> Corrette le cause 1, 2, 3 e 4 (le riaperture rifiutate delle famiglie vecchie passano da 274 a 0). Una nuova caccia (317.038 sequenze, con famiglie nuove su incolla a inizio e fine di voci, liste annidate e selezioni attraverso i contenitori) ha trovato una variante della causa 1, l&#39;incolla di testo nell&#39;etichetta di un wikilink e il volume raddoppiato della causa 6.</p></li><li><p><strong>W9.</strong> Corretti: la casella fuori dal marcatore dopo Invio in un task multiriga, l&#39;incolla nell&#39;etichetta di un wikilink, <code>[^1]</code> a fine enfasi, gli item vuoti annidati, <code>$$</code> in un blocco math, Invio su un intervallo che attraversa blocchi, l&#39;<code>aria-hidden</code> della casella di un bullet diventato task. La caccia indipendente (33.000 sequenze sui task e 46.612 sulle famiglie nuove, semi 5 e 6, nessuna eccezione) ha trovato tre divergenze serie: Maiusc+Invio seguito da un incolla in un task (167 riaperture rifiutate), il delimitatore <code>)</code> che fa perdere le caselle negli elenchi ordinati dentro i task, l&#39;incolla di HTML con blocchi nell&#39;etichetta di un wikilink. La revisione di W9 ne ha aggiunta una quarta: un item con la testa svuotata scritto stretto, con la lista che segue persa in silenzio.</p></li><li><p><strong>W10.</strong> Le quattro sono corrette, ciascuna con un test che fallisce senza la correzione (verificato per mutazione). La correzione del primo punto ha richiesto di scoprire un secondo difetto: un plugin ProseMirror non vede la transazione che ha aggiunto lui, quindi il trim e il mend dei task ora girano in un&#39;unica transazione. <code>live:metrics</code> è identico al baseline (C1-edit 35.041/35.041, C2 non avversario 99,98%, C3 1074/1074, C4 a 0). Dopo W10 non è stata rieseguita una caccia completa.</p></li><li><p><strong>Consolidamento, primo passo (2026-11-12).</strong> Chiusi i tre casi seri trovati dalla revisione di W10. Avevano una causa sola: una voce modificata si riscrive per intero col serializzatore (i suoi figli non stanno nella tabella dei blocchi), e la sua regola di unione mette 0 righe bianche fra i figli di una voce stretta anche dove CommonMark legge i due blocchi come uno. Le regole di <code>compose.ts</code> (<code>needsBlankLine</code>) non arrivano lì, e la rete <code>checked()</code> prendeva per buona proprio quell&#39;uscita: per questo C1-edit e <code>live:metrics</code> non vedevano i tre casi. Le correzioni:</p><ul><li><code>narrowJoin</code> (<code>kit.ts</code>, una <code>join</code> registrata in <code>liveConfig</code>): in un contenitore stretto mette una riga bianca fra una lista, una citazione o una tabella e il paragrafo che segue, e attorno a un blocco raw quando, riletto con il vicino, i due diventerebbero uno. Un file letto non ha mai una di queste coppie senza riga bianca, quindi la regola non scatta sui file che l&#39;utente non ha toccato (test di neutralità sui 1075 file del corpus);</li><li><code>ruleHandler</code> (<code>kit.ts</code>): una regola subito sotto il testo di una voce stretta si scrive <code>***</code> (§9). <code>mendTaskHeads</code> (<code>input/tasks.ts</code>) non rende più larga la voce in quel caso;</li><li><code>replaceWithBlocks</code> (<code>input/paste.ts</code>): un incolla di blocchi a metà riga toglie gli spazi iniziali del testo che segue (§9).</li></ul><p>Prove: <code>input/tightItems.test.ts</code> (16 test sull&#39;editor montato: i tre casi con task, bullet, ordinati <code>.</code> e <code>)</code>, annidati, citazione, CRLF e tabella; testo salvato, <code>extract()</code>, HTML di Reading e riapertura) e 4 test in <code>overrides.test.ts</code> (voci strette, blocchi raw, <code>***</code>, neutralità sul corpus). Verificato per mutazione: senza la <code>join</code> falliscono 8 test, senza il <code>***</code> 10, senza il taglio degli spazi 6. Suite del workbench 157 file e 2163 test passati (46 saltati); <code>live:metrics</code> identico al baseline (C1 1074/1074, C1-edit 35.041/35.041, C2 non avversario 99,98%, C3 1074/1074, C4 a 0); <code>tsc</code>, eslint e prettier puliti. Non eseguiti: <code>task ci</code>, gli e2e Playwright, <code>task parity</code> e una nuova caccia.</p></li><li><p><strong>Consolidamento, passo M16-UX1 (2026-11-12): l&#39;esperienza del playground di Crepe.</strong> Richiesta dell&#39;owner: portare Live all&#39;esperienza di <a href="https://milkdown.dev/playground" target="_blank" rel="noreferrer">https://milkdown.dev/playground</a>. Dietro l&#39;interruttore di build, con il default invariato (CodeMirror). Nuovi: la maniglia dei blocchi, la barra sulla selezione, il tooltip dei link, il segnaposto del blocco vuoto, il popup slash con gruppi e icone, margini più larghi (§9, <code>live/chrome/</code>, <code>live/input/slashLook.ts</code>, <code>live/theme.css</code>). Le icone sono del set Two tone dell&#39;applicazione (D-01), generate in <code>chrome/iconData.ts</code> da <code>scripts/gen-icons.mjs</code> e caricate con il chunk lazy. L&#39;entry desktop a interruttore spento passa comunque da 1992 a 1993 kB (margine 7 kB). Un difetto trovato lungo il passo, riproducibile prima con Alt+↑: spostare un blocco oltre una regola orizzontale faceva sparire la regola e duplicava il blocco, perché i blocchi erano appaiati alle voci del file solo per posizione, e per una regola si riemetteva la fetta della voce appaiata, cioè il testo di un altro blocco. Corretto in <code>fidelity/compose.ts</code>: la fetta si riemette solo se anche la voce appaiata è una regola (<code>forcedBlockOf</code>), i blocchi si appaiano alle voci del file prima per identità e poi per posizione (<code>forcedBlock</code>, con il parametro <code>place</code>), e l&#39;indentazione è quella del posto dove il blocco finisce. Prove: <code>chrome.test.ts</code> (trascinamento, spostamento oltre una regola, stile del posto, fence indentata) e <code>live-chrome.spec.ts</code>. <strong>Residui noti, non corretti:</strong> spostare l&#39;ultima di due liste adiacenti con marcatori diversi può scambiare i loro marcatori; una lista dentro una finestra riscritta può normalizzare <code>* x</code> in <code>* x</code>. Anche l&#39;e2e <code>live-input.spec.ts</code> aveva un&#39;attesa vecchia dal passo precedente (<code>---</code> sotto una voce stretta si scrive <code>***</code>): aggiornata. Non provato su WKWebView, WebView2, WebKitGTK né con un lettore di schermo.</p></li></ul><p><strong>Divergenze note ancora aperte:</strong></p><ul><li><strong>Causa 6:</strong> il redo non riproduce la modifica nelle tabelle dopo l&#39;incolla di blocchi in una cella (serve lavoro sul plugin delle tabelle: il redo passa da <code>fixTables</code>).</li><li><strong>Causa 7:</strong> indentazione irregolare nelle liste, con riscrittura delle righe fratelle quando un incolla o uno split aggiunge blocchi a una voce con marcatore irregolare (serve lavoro in <code>compose.ts</code>).</li><li><strong>Titolo con <code>[[^1]](url)</code>:</strong> alla riapertura diventa <code>raw_block</code>.</li><li><strong>Casi non seri della caccia di W9:</strong> nota riaperta come un unico <code>raw_block</code> con un item vuoto seguito da un blocco o con un task che contiene <code>[^1]</code>; il nuovo task dopo Invio a fine di un task spuntato nasce <code>[x]</code>; l&#39;incolla di un blocco nell&#39;ultimo item di un callout inserisce una riga <code>&gt;</code> vuota fuori dal blocco toccato; l&#39;incolla di HTML in una cella spezza la tabella e l&#39;undo non la ripristina (2 casi).</li><li><strong>Trovato dalla revisione di W10, non corretto:</strong> due a-capo duri di fila al bordo di un paragrafo producono un <code>\\</code> letterale (non serio). Gli altri tre casi di quella revisione, seri, sono chiusi nel primo passo del consolidamento (sopra): la voce larga con la testa svuotata seguita da una tabella o da una citazione e poi da un paragrafo, l&#39;incolla di lista o tabella a metà del testo di una voce stretta, Maiusc+Invio due volte e l&#39;incolla di <code>---</code> che rendeva la voce un titolo setext. Del primo resta un limite già elencato in §9: la voce rimasta senza testo comincia con la tabella o con la citazione, e alla riapertura la sua lista è un <code>raw_block</code> (il significato è conservato, la lista si modifica in Source).</li><li><strong>Fuori dal perimetro dell&#39;editor:</strong> l&#39;escape del backtick in <code>extract()</code> (Go e TS insieme).</li><li><strong>Da confermare con l&#39;owner:</strong> <code> **b.**c</code> si salva <code>**b.**&amp;#x63;</code>, con un riferimento di carattere che l&#39;utente non ha scritto; un task con il solo stato e altri blocchi è scritto <code>-</code>.</li></ul><p><strong>Non provato:</strong> Backspace e Invio nativi del browser (emulati con i comandi di ProseMirror), il code block CodeMirror, il parser Go, Wails reale, <code>task ci</code>. Gli oracoli segnalano come falsi positivi noti <code>%%</code> e <code>$$</code> incollati (aprono un commento o una formula, come in Source) e le parole unite quando l&#39;incolla va in linea.</p><p><strong>Conclusione (superata il 2026-11-12 dalla decisione dell&#39;owner, vedi «Esito di A-W9»).</strong> Prima di rendere Milkdown il default non bastano le prove manuali dell&#39;owner: serve una fase di consolidamento dedicata (avviata il 2026-11-12, con la chiusura dei tre casi seri della revisione di W10), con una caccia differenziale ripetuta fino a esaurimento (nessuna divergenza seria in giri consecutivi con semi e famiglie nuovi) e con le divergenze aperte qui sopra chiuse o accettate esplicitamente.</p><p><strong>Non verificato.</strong> IME su WKWebView, WebView2 e WebKitGTK; spellcheck; lettori di schermo (VoiceOver, NVDA, Orca); incolla da app esterne (Word, browser, altri editor di note, Notes); note reali grandi dell&#39;utente e il peso di <code>LIVE_MAX</code> in una WebView vera; matrice e CSP sulla shell v3; la CSP della shell Wails reale; <code>csp.spec</code> ed <code>excalidraw-offline</code> (non dipendono dall&#39;interruttore, non eseguiti); <code>task ci</code> completo (oggi non prova il motore Milkdown). Prima di rendere Milkdown il default: le liste (accessibilità) e la causa 1 della caccia sono state corrette in W8; restano la decisione sull&#39;apertura lenta, i sei punti da far provare a una persona (roadmap, M16, «Prove che deve fare una persona») e la fase di consolidamento descritta in «Andamento della caccia differenziale».</p><h3 id="esito-di-a-w9-2026-11-12-milkdown-e-l-unico-motore-live" tabindex="-1">Esito di A-W9 (2026-11-12): Milkdown è l&#39;unico motore Live <a class="header-anchor" href="#esito-di-a-w9-2026-11-12-milkdown-e-l-unico-motore-live" aria-label="Permalink to &quot;Esito di A-W9 (2026-11-12): Milkdown è l&#39;unico motore Live&quot;">​</a></h3><p><strong>Decisione dell&#39;owner del 2026-11-12:</strong> Milkdown diventa l&#39;unico motore Live e il predefinito, <strong>senza attendere le prove manuali del cancello A-W8</strong> (IME, spellcheck, lettori di schermo sulle tre WebView). L&#39;ADR passa a «accettata». Source resta su CodeMirror 6 e Reading è invariata.</p><p><strong>Cosa cambia nel codice</strong> (verificato sull&#39;albero di lavoro non committato, <code>git diff HEAD</code>):</p><ul><li><strong>Interruttore rimosso.</strong> <code>liveEngine</code> non c&#39;è più in <code>packages/workbench/build/esbuild.mjs</code> né negli script di build del desktop (<code>apps/desktop/frontend/scripts/esbuild.mjs</code>) e del web (<code>web/scripts/esbuild.mjs</code>). <code>copyTwemojiAssets</code> è incondizionata. <code>NoteEditor.live.tsx</code> è diventato <code>NoteEditor.tsx</code>.</li><li><strong>Vecchio Live cancellato.</strong> <code>editor/livePreview.ts</code>, <code>blockWidgets.ts</code>, <code>widgets.ts</code>, <code>callouts.ts</code>, <code>query/widget.ts</code> (con i loro test), il <code>Facet</code> <code>livePreviewContext</code> e i selettori CSS <code>.cm-lp-*</code>, <code>.cm-wikilink*</code> e <code>.cm-callout*</code>. L&#39;interfaccia <code>LivePreviewContext</code> resta in <code>editor/context.ts</code>; il tipo <code>LinkResolver</code> è in <code>editor/types.ts</code>.</li><li><strong>Source senza <code>Compartment</code> di modalità.</strong> <code>editor/Editor.tsx</code> è diventato <code>editor/source/SourceEditor.tsx</code>, un editor a modalità fissa (Source). <strong>Il disegno di ADR-0004, una sola vista condivisa tra Source e Live con un <code>Compartment</code>, è superato:</strong> <code>docs/adr/0004-live-preview.md</code> passa a «superata (in parte) da ADR-0049». Restano i punti 6 e 7 di ADR-0004 (tasti in Source, Reading) e, come interfaccia e non più come <code>Facet</code>, il 5. Il CodeMirror di Source resta montato sotto Live, come spina dell&#39;undo tra le modalità (§6).</li><li><strong>Moduli solo-CodeMirror in <code>editor/source/</code>:</strong> <code>blockState</code>, <code>sourceMode</code>, <code>commands</code>, <code>completions</code>, <code>external</code>, <code>paste</code>, <code>slash</code> (prima in <code>slash/</code>) e la metà CodeMirror di <code>stats</code>. La regola ESLint <code>engineExempt</code> (<code>eslint.config.js</code>) si riduce a <code>packages/workbench/src/editor/source/**</code>: nessun altro file può importare <code>@codemirror/*</code> o <code>@lezer/*</code>.</li><li><strong>CSS.</strong> Le regole generiche <code>.editor-host .cm-*</code> valgono solo per Source (<code>.editor-host[data-mode=&#39;source&#39;]</code>); i code block di Live hanno il carattere a spaziatura fissa dell&#39;applicazione (<code>.live-host .milkdown-code-block .cm-scroller</code>, <code>--crepe-font-code</code>). Prima, una regola <code>[data-mode=&#39;live&#39;] .cm-scroller</code> faceva usare ai code block il carattere dell&#39;interfaccia.</li><li><strong>Guardie di rilascio.</strong> <code>scripts/release/check-editor-switches.sh</code> rifiuta <code>MEMOBRAIN_AI</code>, <code>MEMOBRAIN_COLLAB</code>, <code>MEMOBRAIN_E2E</code> e <code>MEMOBRAIN_DIST</code> (non più <code>MEMOBRAIN_LIVE_ENGINE</code>). <code>scripts/release/check-dist.sh</code> cerca <code>y-prosemirror</code> (la collaborazione) e il mock dei binding nel <code>dist</code> e <strong>pretende</strong> <code>assets/MilkdownEditor-*.js</code>: senza quel chunk ogni nota si aprirebbe in Source con un avviso. Le guardie girano dove già giravano (<code>build-desktop-bin.sh --release</code>, <code>release/build-desktop.sh --release</code>, <code>task web-build</code>, Dockerfile del cloud).</li><li><strong>Attribuzione Twemoji.</strong> Riga «Licenze» nelle impostazioni, «Informazioni» (<code>settings.licenses</code>, <code>settings.twemojiAttribution</code>), <code>emoji/ATTRIBUTION.txt</code> in ogni build, sezione «Attribuzioni» del README.</li><li><strong>Prove riscritte.</strong> <code>embedLeaks.perf.test.ts</code> ora prova il ciclo di vita degli embed di Live; gli e2e non saltano più per motore; i test del pannello di ricerca di CodeMirror sono diventati test in modalità Source.</li></ul><p><strong>Misure del bundle</strong> (kB, iniziale/totale; limiti nel Taskfile e negli script di build; dichiarate dall&#39;implementatore, non rimisurate da chi ha scritto questo ADR): desktop 1376/18368 (limiti 2000/23000); web workbench 1925/16414 (2500/23000); console web 698 su 700; core WebAssembly 7103 kB gzip su 8192. L&#39;entry desktop scende da 1993 a 1376 kB: il margine, che era di 7 kB e condiviso con ADR-0051, è di circa 624 kB. Nessun limite è stato alzato.</p><p><strong>Prove dichiarate dall&#39;implementatore:</strong> vitest del workbench 2180 passati e 46 saltati; <code>task e2e</code> desktop 179 passati e 4 saltati, desktop-prod 43, console web 94; <code>task e2e-matrix</code> 353 passati, 13 saltati, 0 falliti; <code>task ci</code> con uscita 0.</p><p><strong>Non provato, da fare (seguiti aperti del cancello A-W8):</strong> IME su WKWebView, WebView2 e WebKitGTK; spellcheck; lettori di schermo (VoiceOver, NVDA, Orca); incolla da app esterne (Word, browser, altri editor di note, Notes); note reali grandi e il peso di <code>LIVE_MAX</code> in una WebView vera; matrice e CSP sulla shell Wails reale; la rimisura dell&#39;apertura (2,5 s a 200 kB in Chromium headless, circa 10 volte il vecchio Live, che ormai non c&#39;è per il confronto). Restano aperte anche le divergenze note (cause 6 e 7, titolo con <code>[[^1]](url)</code>, escape del backtick in <code>extract()</code>) e la caccia differenziale non è esaurita. Non provati: Wails reale, WKWebView, WebView2, WebKitGTK, lettori di schermo, IME.</p><p><strong>Da decidere ancora (owner):</strong> aggiornare <code>Specifications.md</code> (punti elencati nella tabella in testa); tenere o togliere <code>linkLazyStyles</code>; la scelta di <code>LIVE_MAX</code> dopo la prova su note reali; le due scelte dell&#39;editor già elencate (task con il solo stato scritto <code>-</code>, <code>\\[^1]</code> tolto nei titoli). ADR-0050 resta <strong>proposta</strong>.</p>',103)])])}const g=o(n,[["render",c]]);export{m as __pageData,g as default};
